import { Attitude3D, BatteryState, MotorState, Vector3D } from './uav';

export type FlightMode =
  | 'DISARMED'
  | 'MANUAL'
  | 'ALT_HOLD'
  | 'POS_HOLD'
  | 'MISSION'
  | 'RTL'
  | 'EMERGENCY_LAND';

export type ArmState = 'DISARMED' | 'ARMING' | 'ARMED';

export interface IMUData {
  accel: Vector3D; // Specific force (m/s^2)
  gyro: Vector3D;  // Angular rates (deg/s)
  vibrationLevel: number; // RMS vibration (g)
}

export interface GPSData {
  latitude: number;
  longitude: number;
  altitudeMsl: number;
  groundSpeedMps: number;
  headingDeg: number;
  satellites: number;
  hdop: number;
  fixType: 'NO_FIX' | '2D_FIX' | '3D_FIX' | 'RTK_FIX';
}

export interface BarometerData {
  pressureHpa: number;
  altitudeMsl: number;
  altitudeAgl: number;
  vsiMps: number; // Vertical speed indicator (m/s)
}

export interface SensorData {
  imu: IMUData;
  gps: GPSData;
  barometer: BarometerData;
  compassHeadingDeg: number;
  airspeedMps: number;
}

export interface TelemetryPacket {
  timestamp: number;
  armState: ArmState;
  flightMode: FlightMode;
  position: Vector3D;
  velocity: Vector3D;
  attitude: Attitude3D;
  sensors: SensorData;
  motors: MotorState[];
  battery: BatteryState;
  activeWaypointIndex: number;
  distanceToHome: number;
  distanceToWaypoint: number;
  warnings: string[];
}

