import { Vector3D } from './uav';

export type WaypointAction = 'NAVIGATE' | 'LOITER' | 'CHANGE_SPEED' | 'PHOTO' | 'LAND';

export interface Waypoint {
  id: string;
  index: number;
  position: Vector3D;     // Local coordinate (meters): X=East, Y=Alt, Z=South
  targetSpeed: number;    // m/s
  loiterSeconds: number;  // seconds to hold position
  action: WaypointAction;
  acceptanceRadius: number; // meters
}

export interface FlightPlan {
  id: string;
  name: string;
  description: string;
  takeoffAltitude: number; // meters
  cruiseSpeed: number;     // m/s
  rtlAltitude: number;     // Return-To-Launch altitude
  geofenceRadius: number;  // Max distance from home (meters)
  waypoints: Waypoint[];
}

