export interface EnvironmentState {
  baseWindSpeed: number;   // m/s
  windDirectionDeg: number;// 0 = North, 90 = East
  windVector: Vector3D;    // m/s in world coordinates
  gustFactor: number;      // 0 to 1
  turbulenceIntensity: number; // 0 (calm) to 1 (severe)
  airDensity: number;      // kg/m^3 (approx 1.225 at sea level)
  temperatureC: number;
}

export class EnvironmentEngine {
  private baseSpeed = 3.0; // m/s
  private windHeading = 45; // deg
  private gustPhase = 0;
  private turbulenceLevel = 0.2;

  public setWind(speed: number, headingDeg: number, turbulence: number): void {
    this.baseSpeed = Math.max(0, speed);
    this.windHeading = headingDeg % 360;
    this.turbulenceLevel = Math.max(0, Math.min(1, turbulence));
  }

  public update(dt: number, altitude: number): EnvironmentState {
    this.gustPhase += dt * 0.7;
    // Multi-frequency wind gust synthesis
    const gust = Math.sin(this.gustPhase) * 0.5 + Math.sin(this.gustPhase * 2.3) * 0.3;
    const currentSpeed = this.baseSpeed + (gust > 0 ? gust * this.baseSpeed * 0.6 : 0);

    // Turbulence micro-fluctuations
    const rad = (this.windHeading * Math.PI) / 180;
    const turbX = (Math.random() - 0.5) * this.turbulenceLevel * 3.0;
    const turbZ = (Math.random() - 0.5) * this.turbulenceLevel * 3.0;
    const turbY = (Math.random() - 0.5) * this.turbulenceLevel * 1.5;

    // World coords: X = East (sin), Z = South (-cos)
    const wx = currentSpeed * Math.sin(rad) + turbX;
    const wz = -currentSpeed * Math.cos(rad) + turbZ;
    const wy = turbY;

    // Atmospheric density lapse rate: standard barometric formula
    const seaLevelDensity = 1.225; // kg/m^3
    const scaleHeight = 8500; // meters
    const airDensity = seaLevelDensity * Math.exp(-Math.max(0, altitude) / scaleHeight);

    return {
      baseWindSpeed: this.baseSpeed,
      windDirectionDeg: this.windHeading,
      windVector: { x: wx, y: wy, z: wz },
      gustFactor: Math.max(0, gust),
      turbulenceIntensity: this.turbulenceLevel,
      airDensity,
      temperatureC: 20 - (altitude * 0.0065),
    };
  }
}

