import { Attitude3D, MotorState, UAVDynamicState, UAVPhysicalParams, Vector3D } from '../types/uav';

export const DEFAULT_UAV_PARAMS: UAVPhysicalParams = {
  mass: 1.8,             // 1.8 kg
  armLength: 0.225,       // 225 mm arm
  dragCoefficient: 0.12,  // Translational aerodynamic drag
  angularDragCoeff: 0.08,
  ixx: 0.0142,            // Roll inertia
  iyy: 0.0250,            // Yaw inertia
  izz: 0.0142,            // Pitch inertia
  thrustCoefficient: 1.5e-6, // N / RPM^2
  torqueCoefficient: 2.2e-8, // N*m / RPM^2
  maxRpm: 18000,
  motorTimeConstant: 0.035,  // 35ms response time
};

export class PhysicsEngine {
  private params: UAVPhysicalParams;
  private state: UAVDynamicState;

  constructor(params = DEFAULT_UAV_PARAMS) {
    this.params = params;
    this.state = this.createInitialState();
  }

  private createInitialState(): UAVDynamicState {
    const motors: MotorState[] = [1, 2, 3, 4].map((id) => ({
      id,
      rpm: 0,
      thrust: 0,
      targetThrottle: 0,
      health: 1.0,
    }));

    return {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      acceleration: { x: 0, y: 0, z: 0 },
      attitude: { roll: 0, pitch: 0, yaw: 0 },
      angularVelocity: { p: 0, q: 0, r: 0 },
      motors,
      battery: {
        voltage: 24.8,
        current: 0,
        capacityUsed: 0,
        totalCapacity: 5000,
        percent: 100,
        cellVoltages: [4.13, 4.13, 4.13, 4.14, 4.13, 4.14],
      },
      timestamp: 0,
      isGrounded: true,
      hasCrashed: false,
    };
  }

  public getState(): UAVDynamicState {
    return this.state;
  }

  public setMotorThrottle(motorIndex: number, throttle: number): void {
    if (this.state.motors[motorIndex]) {
      this.state.motors[motorIndex].targetThrottle = Math.max(0, Math.min(1, throttle));
    }
  }

  public setMotorHealth(motorIndex: number, health: number): void {
    if (this.state.motors[motorIndex]) {
      this.state.motors[motorIndex].health = Math.max(0, Math.min(1, health));
    }
  }

  public reset(spawnAltitude = 0): void {
    this.state = this.createInitialState();
    this.state.position.y = spawnAltitude;
    this.state.isGrounded = spawnAltitude <= 0.05;
  }

  public step(dt: number, windVector: Vector3D, airDensity: number): UAVDynamicState {
    this.state.timestamp += dt;

    // 1. Spool motors with lag & health degradation
    let totalThrust = 0;
    const motorThrusts: number[] = [];
    const rpmToRad = Math.PI / 30;

    for (let i = 0; i < 4; i++) {
      const m = this.state.motors[i];
      const targetRpm = m.targetThrottle * this.params.maxRpm * m.health;
      const dRpm = (targetRpm - m.rpm) * (dt / this.params.motorTimeConstant);
      m.rpm = Math.max(0, m.rpm + dRpm);

      // Thrust T = Ct * density_ratio * (RPM)^2
      const densityRatio = airDensity / 1.225;
      m.thrust = this.params.thrustCoefficient * densityRatio * Math.pow(m.rpm, 2);
      motorThrusts.push(m.thrust);
      totalThrust += m.thrust;
    }

    // 2. Battery electrical load
    const totalWatts = totalThrust * 45.0 + 8.0; // Avionics 8W + ~45W per N thrust
    this.state.battery.current = totalWatts / Math.max(18, this.state.battery.voltage);
    const consumedMah = (this.state.battery.current * dt * 1000) / 3600;
    this.state.battery.capacityUsed = Math.min(
      this.state.battery.totalCapacity,
      this.state.battery.capacityUsed + consumedMah
    );
    this.state.battery.percent = Math.max(
      0,
      100 - (this.state.battery.capacityUsed / this.state.battery.totalCapacity) * 100
    );
    this.state.battery.voltage = 20.0 + (this.state.battery.percent / 100) * 5.0; // 20.0V to 25.0V

    // 3. Torques in body frame
    // Quad-X arrangement: M1 (Front-Right), M2 (Rear-Left), M3 (Front-Left), M4 (Rear-Right)
    const L = this.params.armLength * 0.7071; // 45 deg component
    const tauRoll = L * (motorThrusts[1] + motorThrusts[2] - motorThrusts[0] - motorThrusts[3]);
    const tauPitch = L * (motorThrusts[0] + motorThrusts[2] - motorThrusts[1] - motorThrusts[3]);
    // Reaction torque from rotor drag: M1, M2 are CCW (-), M3, M4 are CW (+)
    const tauYaw = this.params.torqueCoefficient * (
      -Math.pow(this.state.motors[0].rpm, 2) - Math.pow(this.state.motors[1].rpm, 2) +
      Math.pow(this.state.motors[2].rpm, 2) + Math.pow(this.state.motors[3].rpm, 2)
    );

    // 4. Rotational dynamics
    const p = this.state.angularVelocity.p;
    const q = this.state.angularVelocity.q;
    const r = this.state.angularVelocity.r;

    const pDot = (tauRoll + (this.params.iyy - this.params.izz) * q * r - this.params.angularDragCoeff * p) / this.params.ixx;
    const qDot = (tauPitch + (this.params.izz - this.params.ixx) * p * r - this.params.angularDragCoeff * q) / this.params.izz;
    const rDot = (tauYaw + (this.params.ixx - this.params.iyy) * p * q - this.params.angularDragCoeff * r) / this.params.iyy;

    this.state.angularVelocity.p += pDot * dt;
    this.state.angularVelocity.q += qDot * dt;
    this.state.angularVelocity.r += rDot * dt;

    // Attitude integration (Euler angles)
    this.state.attitude.roll += this.state.angularVelocity.p * dt;
    this.state.attitude.pitch += this.state.angularVelocity.q * dt;
    this.state.attitude.yaw = (this.state.attitude.yaw + this.state.angularVelocity.r * dt + Math.PI * 2) % (Math.PI * 2);

    // 5. Translational forces: Body Z-thrust rotated to World coordinates
    // Three.js world frame: +Y is Up, +X is East, +Z is South
    const cr = Math.cos(this.state.attitude.roll);
    const sr = Math.sin(this.state.attitude.roll);
    const cp = Math.cos(this.state.attitude.pitch);
    const sp = Math.sin(this.state.attitude.pitch);
    const cy = Math.cos(this.state.attitude.yaw);
    const sy = Math.sin(this.state.attitude.yaw);

    // Thrust vector in world coords
    const fxThrust = totalThrust * (sy * sp * cr - cy * sr);
    const fyThrust = totalThrust * (cp * cr);
    const fzThrust = totalThrust * (cy * sp * cr + sy * sr);

    // Aerodynamic Drag with relative wind
    const relVx = this.state.velocity.x - windVector.x;
    const relVy = this.state.velocity.y - windVector.y;
    const relVz = this.state.velocity.z - windVector.z;
    const relSpeed = Math.sqrt(relVx * relVx + relVy * relVy + relVz * relVz);
    const dragForceMag = 0.5 * this.params.dragCoefficient * airDensity * relSpeed;

    const fxDrag = -dragForceMag * relVx;
    const fyDrag = -dragForceMag * relVy;
    const fzDrag = -dragForceMag * relVz;

    const gravityForce = -this.params.mass * 9.80665;

    // Linear Accelerations
    const ax = (fxThrust + fxDrag) / this.params.mass;
    const ay = (fyThrust + fyDrag + gravityForce) / this.params.mass;
    const az = (fzThrust + fzDrag) / this.params.mass;

    this.state.acceleration = { x: ax, y: ay, z: az };

    if (this.state.isGrounded) {
      if (fyThrust > -gravityForce * 1.02) {
        this.state.isGrounded = false;
      } else {
        this.state.velocity = { x: 0, y: 0, z: 0 };
        this.state.position.y = 0;
        this.state.attitude.roll *= 0.9;
        this.state.attitude.pitch *= 0.9;
        this.state.angularVelocity = { p: 0, q: 0, r: 0 };
        return this.state;
      }
    }

    // Integrate velocity and position
    this.state.velocity.x += ax * dt;
    this.state.velocity.y += ay * dt;
    this.state.velocity.z += az * dt;

    this.state.position.x += this.state.velocity.x * dt;
    this.state.position.y += this.state.velocity.y * dt;
    this.state.position.z += this.state.velocity.z * dt;

    // Ground contact clamp
    if (this.state.position.y <= 0) {
      this.state.position.y = 0;
      if (Math.abs(this.state.velocity.y) > 4.5 || Math.abs(this.state.attitude.roll) > 0.8 || Math.abs(this.state.attitude.pitch) > 0.8) {
        this.state.hasCrashed = true;
      }
      this.state.velocity = { x: 0, y: 0, z: 0 };
      this.state.angularVelocity = { p: 0, q: 0, r: 0 };
      this.state.isGrounded = true;
    }

    return this.state;
  }
}

