  armLength: 0.225,       // 225 mm arm
  dragCoefficient: 0.12,  // Translational aerodynamic drag
  angularDragCoeff: 0.08,
  ixx: 0.0142,            // Roll inertia
  iyy: 0.0250,            // Yaw inertia
  izz: 0.0142,            // Pitch inertia
  thrustCoefficient: 1.5e-6, // N / RPM^2
  torqueCoefficient: 2.2e-8, // N*m / RPM^2
  maxRpm: 18000,
  motorTimeConstant: 0.035,  // 35ms response time
};

export class PhysicsEngine {
  private params: UAVPhysicalParams;
  private state: UAVDynamicState;

  constructor(params = DEFAULT_UAV_PARAMS) {
    this.params = params;
    this.state = this.createInitialState();
  }

  private createInitialState(): UAVDynamicState {
    const motors: MotorState[] = [1, 2, 3, 4].map((id) => ({
      id,
      rpm: 0,
      thrust: 0,
      targetThrottle: 0,
      health: 1.0,
    }));

    return {
      position: { x: 0, y: 0, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      acceleration: { x: 0, y: 0, z: 0 },
      attitude: { roll: 0, pitch: 0, yaw: 0 },
      angularVelocity: { p: 0, q: 0, r: 0 },
      motors,
      battery: {
        voltage: 24.8,
        current: 0,
        capacityUsed: 0,
        totalCapacity: 5000,
        percent: 100,
        cellVoltages: [4.13, 4.13, 4.13, 4.14, 4.13, 4.14],
      },
      timestamp: 0,
      isGrounded: true,
      hasCrashed: false,
    };
  }

  public getState(): UAVDynamicState {
    return this.state;
  }

  public setMotorThrottle(motorIndex: number, throttle: number): void {
    if (this.state.motors[motorIndex]) {
      this.state.motors[motorIndex].targetThrottle = Math.max(0, Math.min(1, throttle));
    }
  }

  public setMotorHealth(motorIndex: number, health: number): void {
    if (this.state.motors[motorIndex]) {
      this.state.motors[motorIndex].health = Math.max(0, Math.min(1, health));
    }
  }

  public reset(spawnAltitude = 0): void {
    this.state = this.createInitialState();
    this.state.position.y = spawnAltitude;
    this.state.isGrounded = spawnAltitude <= 0.05;
  }

  public step(dt: number, windVector: Vector3D, airDensity: number): UAVDynamicState {
    this.state.timestamp += dt;

    // 1. Spool motors with lag & health degradation
    let totalThrust = 0;
    const motorThrusts: number[] = [];
    const rpmToRad = Math.PI / 30;

    for (let i = 0; i < 4; i++) {
      const m = this.state.motors[i];
      const targetRpm = m.targetThrottle * this.params.maxRpm * m.health;
      const dRpm = (targetRpm - m.rpm) * (dt / this.params.motorTimeConstant);
      m.rpm = Math.max(0, m.rpm + dRpm);

      // Thrust T = Ct * density_ratio * (RPM)^2
      const densityRatio = airDensity / 1.225;
      m.thrust = this.params.thrustCoefficient * densityRatio * Math.pow(m.rpm, 2);
      motorThrusts.push(m.thrust);
      totalThrust += m.thrust;
    }

