    const consumedMah = (this.state.battery.current * dt * 1000) / 3600;
    this.state.battery.capacityUsed = Math.min(
      this.state.battery.totalCapacity,
      this.state.battery.capacityUsed + consumedMah
    );
    this.state.battery.percent = Math.max(
      0,
      100 - (this.state.battery.capacityUsed / this.state.battery.totalCapacity) * 100
    );
    this.state.battery.voltage = 20.0 + (this.state.battery.percent / 100) * 5.0; // 20.0V to 25.0V

    // 3. Torques in body frame
    // Quad-X arrangement: M1 (Front-Right), M2 (Rear-Left), M3 (Front-Left), M4 (Rear-Right)
    const L = this.params.armLength * 0.7071; // 45 deg component
    const tauRoll = L * (motorThrusts[1] + motorThrusts[2] - motorThrusts[0] - motorThrusts[3]);
    const tauPitch = L * (motorThrusts[0] + motorThrusts[2] - motorThrusts[1] - motorThrusts[3]);
    // Reaction torque from rotor drag: M1, M2 are CCW (-), M3, M4 are CW (+)
    const tauYaw = this.params.torqueCoefficient * (
      -Math.pow(this.state.motors[0].rpm, 2) - Math.pow(this.state.motors[1].rpm, 2) +
      Math.pow(this.state.motors[2].rpm, 2) + Math.pow(this.state.motors[3].rpm, 2)
    );

