    const p = this.state.angularVelocity.p;
    const q = this.state.angularVelocity.q;
    const r = this.state.angularVelocity.r;

    const pDot = (tauRoll + (this.params.iyy - this.params.izz) * q * r - this.params.angularDragCoeff * p) / this.params.ixx;
    const qDot = (tauPitch + (this.params.izz - this.params.ixx) * p * r - this.params.angularDragCoeff * q) / this.params.izz;
    const rDot = (tauYaw + (this.params.ixx - this.params.iyy) * p * q - this.params.angularDragCoeff * r) / this.params.iyy;

    this.state.angularVelocity.p += pDot * dt;
    this.state.angularVelocity.q += qDot * dt;
    this.state.angularVelocity.r += rDot * dt;

