    // Three.js world frame: +Y is Up, +X is East, +Z is South
    const cr = Math.cos(this.state.attitude.roll);
    const sr = Math.sin(this.state.attitude.roll);
    const cp = Math.cos(this.state.attitude.pitch);
    const sp = Math.sin(this.state.attitude.pitch);
    const cy = Math.cos(this.state.attitude.yaw);
    const sy = Math.sin(this.state.attitude.yaw);

    // Thrust vector in world coords
    const fxThrust = totalThrust * (sy * sp * cr - cy * sr);
    const fyThrust = totalThrust * (cp * cr);
    const fzThrust = totalThrust * (cy * sp * cr + sy * sr);

    // Aerodynamic Drag with relative wind
    const relVx = this.state.velocity.x - windVector.x;
    const relVy = this.state.velocity.y - windVector.y;
    const relVz = this.state.velocity.z - windVector.z;
    const relSpeed = Math.sqrt(relVx * relVx + relVy * relVy + relVz * relVz);
    const dragForceMag = 0.5 * this.params.dragCoefficient * airDensity * relSpeed;

    const fxDrag = -dragForceMag * relVx;
    const fyDrag = -dragForceMag * relVy;
    const fzDrag = -dragForceMag * relVz;

    const gravityForce = -this.params.mass * 9.80665;

