import { SensorData } from '../types/telemetry';
import { UAVDynamicState } from '../types/uav';

export class SensorEngine {
  private baseLat = 37.6188;  // Reference airfield latitude
  private baseLon = -122.3750; // Reference airfield longitude
  private gyroBias = { x: 0.02, y: -0.01, z: 0.015 };
  private baroNoise = 0.05;
  private prevAltitude = 0;
  private prevTime = 0;
  private vsiFiltered = 0;

  public update(state: UAVDynamicState, airspeedMps: number): SensorData {
    const dt = state.timestamp - this.prevTime || 0.016;
    this.prevTime = state.timestamp;

    // 1. IMU: Accelerometer measures specific force in body frame + motor vibration
    const totalMotorRpm = state.motors.reduce((acc, m) => acc + m.rpm, 0);
    const vibrationAmp = (totalMotorRpm / 72000) * 0.15; // 0 to 0.15g vibration
    const noiseX = (Math.random() - 0.5) * vibrationAmp * 9.81;
    const noiseY = (Math.random() - 0.5) * vibrationAmp * 9.81;
    const noiseZ = (Math.random() - 0.5) * vibrationAmp * 9.81;

    // Specific force = a_world - g_world rotated to body
    const ax = state.acceleration.x + noiseX;
    const ay = state.acceleration.y + 9.80665 + noiseY;
    const az = state.acceleration.z + noiseZ;

    // Gyro with small random walk drift
    const gyroNoise = 0.1; // deg/s
    const degP = (state.angularVelocity.p * 180) / Math.PI + this.gyroBias.x + (Math.random() - 0.5) * gyroNoise;
    const degQ = (state.angularVelocity.q * 180) / Math.PI + this.gyroBias.y + (Math.random() - 0.5) * gyroNoise;
    const degR = (state.angularVelocity.r * 180) / Math.PI + this.gyroBias.z + (Math.random() - 0.5) * gyroNoise;

    // 2. Barometer
    const aglNoise = (Math.random() - 0.5) * this.baroNoise;
    const baroAlt = Math.max(0, state.position.y + aglNoise);
    const rawVsi = (baroAlt - this.prevAltitude) / dt;
    this.vsiFiltered = this.vsiFiltered * 0.85 + rawVsi * 0.15;
