import { PilotInput, UAVPIDConfig } from '../types/controls';
import { Waypoint } from '../types/mission';
import { ArmState, FlightMode } from '../types/telemetry';
import { UAVDynamicState, Vector3D } from '../types/uav';

export const DEFAULT_PID_CONFIG: UAVPIDConfig = {
  rollRate: { kp: 0.14, ki: 0.08, kd: 0.003, maxIntegral: 0.3, outputLimit: 0.8 },
  pitchRate: { kp: 0.14, ki: 0.08, kd: 0.003, maxIntegral: 0.3, outputLimit: 0.8 },
  yawRate: { kp: 0.22, ki: 0.05, kd: 0.002, maxIntegral: 0.2, outputLimit: 0.5 },
  rollAngle: { kp: 4.8, ki: 0.0, kd: 0.15, maxIntegral: 0.2, outputLimit: 2.5 },
  pitchAngle: { kp: 4.8, ki: 0.0, kd: 0.15, maxIntegral: 0.2, outputLimit: 2.5 },
  yawHeading: { kp: 2.2, ki: 0.0, kd: 0.05, maxIntegral: 0.1, outputLimit: 1.8 },
  altitude: { kp: 1.2, ki: 0.02, kd: 0.15, maxIntegral: 0.5, outputLimit: 3.5 },
  velocityVertical: { kp: 0.25, ki: 0.12, kd: 0.015, maxIntegral: 0.4, outputLimit: 0.9 },
  positionHorizontal: { kp: 0.8, ki: 0.0, kd: 0.05, maxIntegral: 0.3, outputLimit: 6.0 },
  velocityHorizontal: { kp: 0.08, ki: 0.03, kd: 0.008, maxIntegral: 0.2, outputLimit: 0.45 },
};

export class AutopilotEngine {
  public pidConfig: UAVPIDConfig = JSON.parse(JSON.stringify(DEFAULT_PID_CONFIG));
  public flightMode: FlightMode = 'DISARMED';
  public armState: ArmState = 'DISARMED';
  public targetPosition: Vector3D = { x: 0, y: 10, z: 0 };
  public targetHeading = 0;
  public activeWaypointIndex = 0;
  public waypoints: Waypoint[] = [];
  public rtlAltitude = 20;

  // Integrator states
  private intAlt = 0;
  private intVy = 0;
  private intVx = 0;
  private intVz = 0;
  private intRollRate = 0;
  private intPitchRate = 0;
  private intYawRate = 0;

  public setFlightMode(mode: FlightMode): void {
    this.flightMode = mode;
  }

  public setArmState(state: ArmState): void {
    this.armState = state;
    if (state === 'DISARMED') {
      this.flightMode = 'DISARMED';
      this.resetIntegrators();
    }
  }

  public resetIntegrators(): void {
    this.intAlt = 0;
    this.intVy = 0;
    this.intVx = 0;
    this.intVz = 0;
    this.intRollRate = 0;
    this.intPitchRate = 0;
    this.intYawRate = 0;
  }

  public computeMotorOutputs(
    state: UAVDynamicState,
    dt: number,
    pilot: PilotInput
  ): number[] {
    if (this.armState !== 'ARMED' || this.flightMode === 'DISARMED') {
      return [0, 0, 0, 0];
    }

    // Determine target roll, pitch, yaw rate, and collective thrust
    let targetRoll = 0;
    let targetPitch = 0;
    let targetYawRate = 0;
    let collectiveThrust = 0.42; // Base hover throttle for 1.8kg quad

    if (this.flightMode === 'MANUAL') {
      targetRoll = pilot.roll * 0.45; // Max ~25 deg bank
      targetPitch = pilot.pitch * 0.45;
      targetYawRate = pilot.yaw * 1.5; // rad/s
      collectiveThrust = pilot.throttle;
    } else {
      // Autonomous guidance modes (ALT_HOLD, POS_HOLD, MISSION, RTL, EMERGENCY_LAND)
      collectiveThrust = this.computeAltitudeControl(state, dt, pilot);

      if (this.flightMode === 'ALT_HOLD') {
        targetRoll = pilot.roll * 0.45;
        targetPitch = pilot.pitch * 0.45;
        targetYawRate = pilot.yaw * 1.5;
      } else {
        // Navigation modes
        this.updateWaypointNavigation(state);
        const attitudeCmd = this.computePositionControl(state, dt);
        targetRoll = attitudeCmd.targetRoll;
        targetPitch = attitudeCmd.targetPitch;
        targetYawRate = attitudeCmd.targetYawRate;
      }
    }

    // Attitude loop -> Angular rate commands
    const errRoll = targetRoll - state.attitude.roll;
    const targetP = errRoll * this.pidConfig.rollAngle.kp - state.angularVelocity.p * this.pidConfig.rollAngle.kd;

    const errPitch = targetPitch - state.attitude.pitch;
    const targetQ = errPitch * this.pidConfig.pitchAngle.kp - state.angularVelocity.q * this.pidConfig.pitchAngle.kd;

    // Angular rate PID -> Torques
    const errP = targetP - state.angularVelocity.p;
    this.intRollRate = Math.max(-0.2, Math.min(0.2, this.intRollRate + errP * dt * this.pidConfig.rollRate.ki));
    const tauX = errP * this.pidConfig.rollRate.kp + this.intRollRate;

    const errQ = targetQ - state.angularVelocity.q;
    this.intPitchRate = Math.max(-0.2, Math.min(0.2, this.intPitchRate + errQ * dt * this.pidConfig.pitchRate.ki));
    const tauZ = errQ * this.pidConfig.pitchRate.kp + this.intPitchRate;

    const errR = targetYawRate - state.angularVelocity.r;
    this.intYawRate = Math.max(-0.15, Math.min(0.15, this.intYawRate + errR * dt * this.pidConfig.yawRate.ki));
    const tauY = errR * this.pidConfig.yawRate.kp + this.intYawRate;

    // Quad-X Motor Mixer
    // M1 (FR): -Roll +Pitch -Yaw
    // M2 (RL): +Roll -Pitch -Yaw
    // M3 (FL): +Roll +Pitch +Yaw
    // M4 (RR): -Roll -Pitch +Yaw
    const m1 = collectiveThrust - tauX + tauZ - tauY;
    const m2 = collectiveThrust + tauX - tauZ - tauY;
    const m3 = collectiveThrust + tauX + tauZ + tauY;
    const m4 = collectiveThrust - tauX - tauZ + tauY;

    return [
      Math.max(0.05, Math.min(1.0, m1)),
      Math.max(0.05, Math.min(1.0, m2)),
      Math.max(0.05, Math.min(1.0, m3)),
      Math.max(0.05, Math.min(1.0, m4)),
    ];
  }

  private computeAltitudeControl(state: UAVDynamicState, dt: number, pilot: PilotInput): number {
    let targetAlt = this.targetPosition.y;
    if (this.flightMode === 'ALT_HOLD') {
      this.targetPosition.y += (pilot.throttle - 0.5) * dt * 4.0;
      targetAlt = this.targetPosition.y;
    } else if (this.flightMode === 'EMERGENCY_LAND') {
      this.targetPosition.y = Math.max(0, this.targetPosition.y - dt * 1.2);
      targetAlt = this.targetPosition.y;
    }

    const altErr = targetAlt - state.position.y;
    const targetVy = Math.max(-2.5, Math.min(3.0, altErr * this.pidConfig.altitude.kp));

    const vyErr = targetVy - state.velocity.y;
    this.intVy = Math.max(-0.25, Math.min(0.25, this.intVy + vyErr * dt * this.pidConfig.velocityVertical.ki));
    const throttleAdj = vyErr * this.pidConfig.velocityVertical.kp + this.intVy;

    return Math.max(0.1, Math.min(0.9, 0.42 + throttleAdj));
  }

  private updateWaypointNavigation(state: UAVDynamicState): void {
    if (this.flightMode === 'MISSION' && this.waypoints.length > 0) {
      const currentWp = this.waypoints[this.activeWaypointIndex];
      if (currentWp) {
        this.targetPosition = currentWp.position;
        const dx = currentWp.position.x - state.position.x;
        const dz = currentWp.position.z - state.position.z;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist < currentWp.acceptanceRadius) {
          if (this.activeWaypointIndex < this.waypoints.length - 1) {
            this.activeWaypointIndex++;
          } else {
            this.flightMode = 'POS_HOLD';
          }
        }
      }
    } else if (this.flightMode === 'RTL') {
      const distHome = Math.sqrt(state.position.x * state.position.x + state.position.z * state.position.z);
      if (state.position.y < this.rtlAltitude && distHome > 4.0) {
        this.targetPosition = { x: state.position.x, y: this.rtlAltitude, z: state.position.z };
      } else if (distHome > 2.0) {
        this.targetPosition = { x: 0, y: this.rtlAltitude, z: 0 };
      } else {
        this.targetPosition = { x: 0, y: 0, z: 0 };
        this.flightMode = 'EMERGENCY_LAND';
      }
    }
  }

  private computePositionControl(state: UAVDynamicState, dt: number) {
    const errX = this.targetPosition.x - state.position.x;
    const errZ = this.targetPosition.z - state.position.z;

    const targetVx = Math.max(-8.0, Math.min(8.0, errX * this.pidConfig.positionHorizontal.kp));
    const targetVz = Math.max(-8.0, Math.min(8.0, errZ * this.pidConfig.positionHorizontal.kp));

    const errVx = targetVx - state.velocity.x;
    const errVz = targetVz - state.velocity.z;

    this.intVx = Math.max(-0.2, Math.min(0.2, this.intVx + errVx * dt * this.pidConfig.velocityHorizontal.ki));
    this.intVz = Math.max(-0.2, Math.min(0.2, this.intVz + errVz * dt * this.pidConfig.velocityHorizontal.ki));

    // World acceleration targets
    const axCmd = errVx * this.pidConfig.velocityHorizontal.kp + this.intVx;
    const azCmd = errVz * this.pidConfig.velocityHorizontal.kp + this.intVz;

    // Rotate world acceleration to body roll and pitch using current yaw
    const cy = Math.cos(state.attitude.yaw);
    const sy = Math.sin(state.attitude.yaw);

    const targetRoll = Math.max(-0.4, Math.min(0.4, (-axCmd * cy - azCmd * sy)));
    const targetPitch = Math.max(-0.4, Math.min(0.4, (axCmd * sy - azCmd * cy)));

    // Heading alignment toward target
    const targetHeading = Math.atan2(errX, -errZ);
    let headingErr = targetHeading - state.attitude.yaw;
    while (headingErr > Math.PI) headingErr -= Math.PI * 2;
    while (headingErr < -Math.PI) headingErr += Math.PI * 2;
    const targetYawRate = Math.max(-1.0, Math.min(1.0, headingErr * this.pidConfig.yawHeading.kp));

    return { targetRoll, targetPitch, targetYawRate };
  }
}

