export class SoundEngine {
  private audioCtx: AudioContext | null = null;
  private motorGain: GainNode | null = null;
  private windGain: GainNode | null = null;
  private oscillators: OscillatorNode[] = [];
  private isMuted = true;
  private isInitialized = false;

  public init(): void {
    if (this.isInitialized) return;
    try {
      const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.audioCtx = new AudioContextClass();

      // Master motor sound gain
      this.motorGain = this.audioCtx.createGain();
      this.motorGain.gain.setValueAtTime(0, this.audioCtx.currentTime);
      this.motorGain.connect(this.audioCtx.destination);

      // Create 4 harmonic oscillators for quadcopter motor hum
      const harmonics = [1.0, 2.0, 3.5, 5.0];
      for (const h of harmonics) {
        const osc = this.audioCtx.createOscillator();
        osc.type = h > 3.0 ? 'triangle' : 'sawtooth';
        osc.frequency.setValueAtTime(100 * h, this.audioCtx.currentTime);

        const oscGain = this.audioCtx.createGain();
        oscGain.gain.setValueAtTime(0.08 / h, this.audioCtx.currentTime);
        osc.connect(oscGain);
        oscGain.connect(this.motorGain);
        osc.start();
        this.oscillators.push(osc);
      }

      this.isInitialized = true;
    } catch {
      // AudioContext unavailable or blocked
    }
  }

  public setMute(muted: boolean): void {
    this.isMuted = muted;
    if (!muted && !this.isInitialized) {
      this.init();
    }
    if (this.audioCtx && this.audioCtx.state === 'suspended') {
      this.audioCtx.resume();
    }
    if (this.motorGain && this.audioCtx) {
      this.motorGain.gain.setTargetAtTime(this.isMuted ? 0 : 0.12, this.audioCtx.currentTime, 0.05);
    }
  }

  public getMuted(): boolean {
    return this.isMuted;
  }

  public update(avgRpm: number, airspeed: number): void {
    if (this.isMuted || !this.audioCtx || !this.isInitialized) return;

    // Base blade passing frequency: (RPM / 60) * 2 blades
    const bpf = Math.max(40, (avgRpm / 60) * 2.0);
    const now = this.audioCtx.currentTime;

    const harmonics = [1.0, 2.0, 3.5, 5.0];
    this.oscillators.forEach((osc, idx) => {
      const freq = bpf * harmonics[idx];
      osc.frequency.setTargetAtTime(Math.min(8000, freq), now, 0.04);
    });

    if (this.motorGain) {
      const vol = avgRpm > 100 ? Math.min(0.2, (avgRpm / 18000) * 0.18 + 0.02) : 0;
      this.motorGain.gain.setTargetAtTime(vol, now, 0.04);
    }
  }
}

export const soundEngine = new SoundEngine();

