import { TelemetryPacket } from '../types/telemetry';

export class FlightRecorder {
  private frames: TelemetryPacket[] = [];
  private maxFrames = 12000; // ~10 minutes at 20Hz
  private isRecording = true;

  public addFrame(packet: TelemetryPacket): void {
    if (!this.isRecording) return;
    this.frames.push(JSON.parse(JSON.stringify(packet)));
    if (this.frames.length > this.maxFrames) {
      this.frames.shift();
    }
  }

  public getFrames(): TelemetryPacket[] {
    return this.frames;
  }

  public getFrameCount(): number {
    return this.frames.length;
  }

  public getFrameAt(index: number): TelemetryPacket | null {
    if (index >= 0 && index < this.frames.length) {
      return this.frames[index];
    }
    return null;
  }

  public clear(): void {
    this.frames = [];
  }

  public setRecording(recording: boolean): void {
    this.isRecording = recording;
  }

  public exportCSV(): string {
    if (this.frames.length === 0) return '';
    const headers = [
      'Timestamp_s',
      'FlightMode',
      'PosX_m',
      'PosY_Alt_m',
      'PosZ_m',
      'VelX_mps',
      'VelY_mps',
      'VelZ_mps',
      'Roll_deg',
      'Pitch_deg',
      'Yaw_deg',
      'Vibration_g',
      'Battery_V',
      'Battery_A',
      'Battery_pct',
      'Motor1_RPM',
      'Motor2_RPM',
      'Motor3_RPM',
      'Motor4_RPM',
    ].join(',');

    const rows = this.frames.map((f) => {
      const rollDeg = ((f.attitude.roll * 180) / Math.PI).toFixed(2);
      const pitchDeg = ((f.attitude.pitch * 180) / Math.PI).toFixed(2);
      const yawDeg = ((f.attitude.yaw * 180) / Math.PI).toFixed(2);
      return [
        f.timestamp.toFixed(2),
        f.flightMode,
        f.position.x.toFixed(2),
        f.position.y.toFixed(2),
        f.position.z.toFixed(2),
        f.velocity.x.toFixed(2),
        f.velocity.y.toFixed(2),
        f.velocity.z.toFixed(2),
        rollDeg,
        pitchDeg,
        yawDeg,
        f.sensors.imu.vibrationLevel.toFixed(3),
        f.battery.voltage.toFixed(2),
        f.battery.current.toFixed(2),
        f.battery.percent.toFixed(1),
        f.motors[0]?.rpm.toFixed(0) || '0',
        f.motors[1]?.rpm.toFixed(0) || '0',
        f.motors[2]?.rpm.toFixed(0) || '0',
        f.motors[3]?.rpm.toFixed(0) || '0',
      ].join(',');
    });

    return [headers, ...rows].join('\n');
  }

  public downloadCSV(): void {
    const csv = this.exportCSV();
    if (!csv) return;
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `flight_log_${new Date().toISOString().replace(/[:.]/g, '-')}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  }
}

export const flightRecorder = new FlightRecorder();

