  --border-active: rgba(0, 242, 254, 0.45);
  --accent-cyan: #00f2fe;
  --accent-blue: #4facfe;
  --accent-emerald: #00f5a0;
  --accent-amber: #f6d365;
  --accent-rose: #ff416c;
  --text-main: #f0f4f8;
  --text-muted: #8a99ad;
  --font-mono: 'JetBrains Mono', monospace;
  --font-display: 'Rajdhani', sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-primary);
  color: var(--text-main);
  font-family: var(--font-mono);
  overflow-x: hidden;
  user-select: none;
}

/* Glassmorphism Tactical Panel */
.tactical-panel {
  background: var(--bg-panel);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  backdrop-filter: blur(12px);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.45);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.tactical-panel:hover {
  border-color: var(--border-active);
}

.tactical-title {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

/* Custom Tactical Scrollbars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.2);
}
::-webkit-scrollbar-thumb {
  background: var(--border-subtle);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--accent-cyan);
}

/* Glowing Neon Elements */
.glow-cyan {
  text-shadow: 0 0 10px rgba(0, 242, 254, 0.6);
}
.glow-emerald {
  text-shadow: 0 0 10px rgba(0, 245, 160, 0.6);
}
.glow-rose {
  text-shadow: 0 0 10px rgba(255, 65, 108, 0.6);
}

/* Scanline Overlay for PFD and Viewport */
.scanlines {
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%,
    rgba(0, 0, 0, 0.25) 50%
  );
  background-size: 100% 4px;
  pointer-events: none;
}

/* Button & Hitbox styling conforming to Interface Doctrine */
.tactical-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  background: rgba(13, 18, 29, 0.7);
  color: var(--text-main);
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.05em;
  cursor: pointer;
  transition: all 0.15s ease;
}

.tactical-btn:hover {
  background: rgba(0, 242, 254, 0.12);
  border-color: var(--accent-cyan);
  color: #fff;
}

.tactical-btn-primary {
  background: rgba(0, 242, 254, 0.2);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
}

.tactical-btn-primary:hover {
  background: var(--accent-cyan);
  color: #07090e;
}

.tactical-btn-danger {
  background: rgba(255, 65, 108, 0.15);
  border-color: var(--accent-rose);
  color: var(--accent-rose);
}

.tactical-btn-danger:hover {
  background: var(--accent-rose);
  color: #fff;
}

