import React from 'react';
import {
  AlertTriangle,
  Battery,
  Compass,
  Power,
  RotateCcw,
  ShieldAlert,
  Volume2,
  VolumeX,
} from 'lucide-react';
import { ArmState, FlightMode, TelemetryPacket } from '../types/telemetry';

interface HeaderProps {
  telemetry: TelemetryPacket;
  armState: ArmState;
  flightMode: FlightMode;
  isAudioMuted: boolean;
  onToggleArm: () => void;
  onSelectFlightMode: (mode: FlightMode) => void;
  onToggleAudio: () => void;
  onResetUav: () => void;
}

export const Header: React.FC<HeaderProps> = ({
  telemetry,
  armState,
  flightMode,
  isAudioMuted,
  onToggleArm,
  onSelectFlightMode,
  onToggleAudio,
  onResetUav,
}) => {
  const isArmed = armState === 'ARMED';
  const batteryPct = telemetry.battery.percent;

  const modes: { label: string; mode: FlightMode }[] = [
    { label: 'MAN', mode: 'MANUAL' },
    { label: 'ALT', mode: 'ALT_HOLD' },
    { label: 'POS', mode: 'POS_HOLD' },
    { label: 'AUTO', mode: 'MISSION' },
    { label: 'RTL', mode: 'RTL' },
    { label: 'LAND', mode: 'EMERGENCY_LAND' },
  ];

  return (
    <header className="tactical-panel" style={{
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      height: '64px',
      padding: '0 20px',
      margin: '8px 8px 4px 8px',
      borderLeft: isArmed ? '4px solid var(--accent-emerald)' : '4px solid var(--accent-amber)',
    }}>
      {/* Aircraft Callout */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
        <div style={{
          width: '38px',
          height: '38px',
          borderRadius: '6px',
          background: 'rgba(0, 242, 254, 0.1)',
          border: '1px solid var(--border-subtle)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: 'var(--accent-cyan)',
        }}>
          <Compass size={22} />
        </div>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span className="tactical-title" style={{ fontSize: '18px', color: '#fff' }}>
              FAUST-AERO // X4-SIM
            </span>
            <span style={{
              fontSize: '10px',
              padding: '2px 6px',
              borderRadius: '4px',
              background: 'rgba(0, 242, 254, 0.15)',
              color: 'var(--accent-cyan)',
              border: '1px solid var(--border-subtle)',
            }}>
              FAT-CERTIFIED
            </span>
          </div>
          <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
            GCS LINK: <span style={{ color: 'var(--accent-emerald)' }}>ONLINE (50Hz)</span> | HDOP: {telemetry.sensors.gps.hdop.toFixed(1)} | SATS: {telemetry.sensors.gps.satellites}
          </div>
        </div>
      </div>

      {/* Flight Modes Selector */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
        {modes.map((m) => {
          const isActive = flightMode === m.mode;
          return (
            <button
              key={m.mode}
              onClick={() => onSelectFlightMode(m.mode)}
              className="tactical-btn"
              style={{
                minHeight: '34px',
                padding: '0 12px',
                fontSize: '12px',
                background: isActive ? 'rgba(0, 242, 254, 0.25)' : 'rgba(13, 18, 29, 0.6)',
                borderColor: isActive ? 'var(--accent-cyan)' : 'var(--border-subtle)',
                color: isActive ? 'var(--accent-cyan)' : 'var(--text-muted)',
              }}
            >
              {m.label}
            </button>
          );
        })}
      </div>

      {/* Arm Control & Telemetry Badges */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
        {/* Warning Indicator */}
        {telemetry.warnings.length > 0 && (
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '6px',
            color: 'var(--accent-rose)',
            fontSize: '12px',
            fontWeight: 700,
          }}>
            <AlertTriangle size={16} />
            <span>{telemetry.warnings[0]}</span>
          </div>
        )}

        {/* Battery Gauge */}
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          padding: '4px 10px',
          borderRadius: '6px',
          background: 'rgba(0, 0, 0, 0.3)',
          border: '1px solid var(--border-subtle)',
        }}>
          <Battery size={18} color={batteryPct > 30 ? 'var(--accent-emerald)' : 'var(--accent-rose)'} />
          <div style={{ fontSize: '12px', fontFamily: 'var(--font-mono)' }}>
            <span style={{ fontWeight: 700, color: '#fff' }}>{batteryPct.toFixed(0)}%</span>
            <span style={{ fontSize: '10px', color: 'var(--text-muted)', marginLeft: '4px' }}>
              ({telemetry.battery.voltage.toFixed(1)}V)
            </span>
          </div>
        </div>

        {/* Audio Toggle */}
        <button
          onClick={onToggleAudio}
          className="tactical-btn"
          style={{ width: '36px', height: '36px', minHeight: '36px', padding: 0 }}
          title={isAudioMuted ? 'Unmute Sound' : 'Mute Sound'}
        >
          {isAudioMuted ? <VolumeX size={16} color="var(--text-muted)" /> : <Volume2 size={16} color="var(--accent-cyan)" />}
        </button>

        {/* Reset UAV */}
        <button
          onClick={onResetUav}
          className="tactical-btn"
          style={{ width: '36px', height: '36px', minHeight: '36px', padding: 0 }}
          title="Reset Aircraft to Launchpad"
        >
          <RotateCcw size={16} />
        </button>

        {/* Master Arm Switch */}
        <button
          onClick={onToggleArm}
          className={`tactical-btn ${isArmed ? 'tactical-btn-danger' : 'tactical-btn-primary'}`}
          style={{
            minHeight: '38px',
            padding: '0 18px',
            fontWeight: 700,
            fontSize: '13px',
          }}
        >
          {isArmed ? <ShieldAlert size={16} /> : <Power size={16} />}
          <span>{isArmed ? 'DISARM MOTORS' : 'ARM SYSTEM'}</span>
        </button>
      </div>
    </header>
  );
};

