import React, { useEffect, useRef } from 'react';
import { TelemetryPacket } from '../types/telemetry';

interface PfdProps {
  telemetry: TelemetryPacket;
  targetAltitude: number;
  targetHeading: number;
}

export const PrimaryFlightDisplay: React.FC<PfdProps> = ({
  telemetry,
  targetAltitude,
  targetHeading,
}) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const cx = width / 2;
    const cy = height / 2;

    const roll = telemetry.attitude.roll;
    const pitch = telemetry.attitude.pitch;
    const alt = telemetry.sensors.barometer.altitudeAgl;
    const speed = telemetry.sensors.airspeedMps;
    const vsi = telemetry.sensors.barometer.vsiMps;
    const heading = (telemetry.attitude.yaw * 180) / Math.PI;

    // Clear background
    ctx.clearRect(0, 0, width, height);

    // 1. Draw Artificial Horizon
    ctx.save();
    // Clip to central horizon circle/rectangle
    ctx.beginPath();
    ctx.rect(45, 20, width - 90, height - 55);
    ctx.clip();

    ctx.translate(cx, cy);
    ctx.rotate(-roll);

    const pitchPixelsPerRad = 260;
    const pitchOffset = pitch * pitchPixelsPerRad;

    // Sky
    ctx.fillStyle = '#0f2942';
    ctx.fillRect(-width, -height * 2 + pitchOffset, width * 2, height * 2);

    // Ground
    ctx.fillStyle = '#221914';
    ctx.fillRect(-width, pitchOffset, width * 2, height * 2);

    // Horizon line
    ctx.strokeStyle = '#00f2fe';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-width, pitchOffset);
    ctx.lineTo(width, pitchOffset);
    ctx.stroke();

    // Pitch ladder rungs (-40 to +40 deg)
    ctx.fillStyle = '#ffffff';
    ctx.font = '10px "JetBrains Mono"';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.7)';

    for (let deg = -40; deg <= 40; deg += 10) {
      if (deg === 0) continue;
      const rad = (deg * Math.PI) / 180;
      const y = pitchOffset - rad * pitchPixelsPerRad;
      const rungWidth = Math.abs(deg) % 20 === 0 ? 50 : 30;

      ctx.beginPath();
      ctx.moveTo(-rungWidth, y);
      ctx.lineTo(-12, y);
      ctx.moveTo(12, y);
      ctx.lineTo(rungWidth, y);
      ctx.stroke();

      ctx.fillText(`${Math.abs(deg)}`, -rungWidth - 12, y);
      ctx.fillText(`${Math.abs(deg)}`, rungWidth + 12, y);
    }
    ctx.restore();

    // 2. Center Aircraft Reticle (Yellow/Cyan wings)
    ctx.save();
    ctx.strokeStyle = '#f6d365';
    ctx.lineWidth = 3;
    ctx.beginPath();
    // Left wing
    ctx.moveTo(cx - 45, cy);
    ctx.lineTo(cx - 16, cy);
    ctx.lineTo(cx - 16, cy + 8);
    // Right wing
    ctx.moveTo(cx + 45, cy);
    ctx.lineTo(cx + 16, cy);
    ctx.lineTo(cx + 16, cy + 8);
    // Center pip
    ctx.moveTo(cx - 3, cy);
    ctx.lineTo(cx + 3, cy);
    ctx.stroke();

    ctx.fillStyle = '#f6d365';
    ctx.beginPath();
    ctx.arc(cx, cy, 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

