    ctx.fillStyle = '#00f2fe';
    ctx.fillRect(2, cy - 10, 41, 20);
    ctx.fillStyle = '#07090e';
    ctx.font = 'bold 11px "JetBrains Mono"';
    ctx.textAlign = 'center';
    ctx.fillText(`${speed.toFixed(1)}`, 22, cy + 4);

    // 5. Altitude Tape (Right side: x = width - 45 to width)
    const tapeX = width - 45;
    ctx.fillStyle = 'rgba(7, 9, 14, 0.85)';
    ctx.fillRect(tapeX, 20, 45, height - 55);
    ctx.strokeStyle = 'var(--border-subtle)';
    ctx.strokeRect(tapeX, 20, 45, height - 55);

    ctx.fillStyle = '#fff';
    ctx.font = '10px "JetBrains Mono"';
    ctx.textAlign = 'left';
    for (let a = Math.floor(alt - 8); a <= Math.ceil(alt + 8); a += 2) {
      if (a < 0) continue;
      const dy = cy - (a - alt) * 10;
      if (dy > 25 && dy < height - 40) {
        ctx.strokeStyle = 'rgba(255,255,255,0.4)';
        ctx.beginPath();
        ctx.moveTo(tapeX, dy);
        ctx.lineTo(tapeX + 10, dy);
        ctx.stroke();
        ctx.fillText(`${a}`, tapeX + 14, dy + 3);
      }
    }
    // Target altitude bug
    const bugY = cy - (targetAltitude - alt) * 10;
    if (bugY > 25 && bugY < height - 40) {
      ctx.fillStyle = '#f6d365';
      ctx.beginPath();
      ctx.moveTo(tapeX - 4, bugY);
      ctx.lineTo(tapeX, bugY - 5);
      ctx.lineTo(tapeX, bugY + 5);
      ctx.closePath();
      ctx.fill();
    }
    // Altitude readout box
    ctx.fillStyle = '#00f5a0';
    ctx.fillRect(tapeX + 2, cy - 10, 41, 20);
    ctx.fillStyle = '#07090e';
    ctx.font = 'bold 11px "JetBrains Mono"';
    ctx.textAlign = 'center';
    ctx.fillText(`${alt.toFixed(1)}`, tapeX + 22, cy + 4);

    // 6. Heading Compass Tape (Bottom: y = height - 35 to height)
    const hY = height - 32;
    ctx.fillStyle = 'rgba(7, 9, 14, 0.9)';
    ctx.fillRect(45, hY, width - 90, 30);
    ctx.strokeStyle = 'var(--border-subtle)';
    ctx.strokeRect(45, hY, width - 90, 30);

    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.font = '9px "JetBrains Mono"';

    const headingNorm = (heading % 360 + 360) % 360;
    for (let h = Math.floor(headingNorm - 35); h <= Math.ceil(headingNorm + 35); h += 5) {
      const normH = (h % 360 + 360) % 360;
      const dx = cx + (h - headingNorm) * 3.5;
      if (dx > 50 && dx < width - 50) {
        ctx.strokeStyle = normH % 15 === 0 ? 'rgba(255,255,255,0.7)' : 'rgba(255,255,255,0.3)';
        ctx.beginPath();
        ctx.moveTo(dx, hY);
        ctx.lineTo(dx, hY + (normH % 15 === 0 ? 8 : 4));
        ctx.stroke();

        if (normH % 15 === 0) {
          let label = `${normH}`;
          if (normH === 0) label = 'N';
          if (normH === 90) label = 'E';
          if (normH === 180) label = 'S';
          if (normH === 270) label = 'W';
          ctx.fillText(label, dx, hY + 18);
        }
      }
    }
    // Heading center pointer
    ctx.fillStyle = '#00f2fe';
    ctx.beginPath();
    ctx.moveTo(cx, hY + 1);
    ctx.lineTo(cx - 5, hY + 8);
    ctx.lineTo(cx + 5, hY + 8);
    ctx.closePath();
    ctx.fill();
  }, [telemetry, targetAltitude, targetHeading]);

  return (
    <div className="tactical-panel" style={{ padding: '8px', position: 'relative' }}>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: '4px',
        padding: '0 4px',
      }}>
        <span className="tactical-title" style={{ fontSize: '13px', color: 'var(--accent-cyan)' }}>
          PRIMARY FLIGHT DISPLAY (PFD)
        </span>
        <span style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
          MODE: <span style={{ color: '#fff', fontWeight: 700 }}>{telemetry.flightMode}</span>
        </span>
      </div>
      <canvas
        ref={canvasRef}
        width={320}
        height={260}
        style={{
          width: '100%',
          height: '240px',
          borderRadius: '4px',
          display: 'block',
          background: '#07090e',
        }}
      />
    </div>
  );
};

