import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { Waypoint } from '../types/mission';
import { TelemetryPacket } from '../types/telemetry';
import { Vector3D } from '../types/uav';

interface Viewport3DProps {
  telemetry: TelemetryPacket;
  waypoints: Waypoint[];
  windVector: Vector3D;
}

export type CameraMode = 'CHASE' | 'FPV' | 'TACTICAL' | 'GROUND';

export const Viewport3D: React.FC<Viewport3DProps> = ({
  telemetry,
  waypoints,
  windVector,
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [cameraMode, setCameraMode] = useState<CameraMode>('CHASE');

  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const uavGroupRef = useRef<THREE.Group | null>(null);
  const rotorMeshesRef = useRef<THREE.Mesh[]>([]);
  const trailLineRef = useRef<THREE.Line | null>(null);
  const trailPointsRef = useRef<THREE.Vector3[]>([]);
  const waypointsGroupRef = useRef<THREE.Group | null>(null);
  const windsockRef = useRef<THREE.Group | null>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // 1. Scene, Camera, Renderer
    const scene = new THREE.Scene();
    sceneRef.current = scene;
    scene.background = new THREE.Color(0x06080d);
    scene.fog = new THREE.FogExp2(0x06080d, 0.005);

    const camera = new THREE.PerspectiveCamera(55, container.clientWidth / container.clientHeight, 0.2, 800);
    cameraRef.current = camera;
    camera.position.set(0, 8, 14);

    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    rendererRef.current = renderer;
    renderer.setSize(container.clientWidth, container.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    container.appendChild(renderer.domElement);

    // 2. Lighting
    const ambient = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambient);

    const sun = new THREE.DirectionalLight(0xdff4ff, 1.2);
    sun.position.set(40, 80, 50);
    sun.castShadow = true;
    scene.add(sun);

    // 3. Airfield & Ground
    const grid = new THREE.GridHelper(300, 60, 0x00f2fe, 0x162233);
    grid.position.y = 0;
    scene.add(grid);

    // Runway tarmac
    const tarmacGeo = new THREE.PlaneGeometry(16, 120);
    const tarmacMat = new THREE.MeshStandardMaterial({ color: 0x111622, roughness: 0.8 });
    const tarmac = new THREE.Mesh(tarmacGeo, tarmacMat);
    tarmac.rotation.x = -Math.PI / 2;
    tarmac.position.set(0, 0.02, 0);
    scene.add(tarmac);

    // Helipad / Launch circle
    const padGeo = new THREE.RingGeometry(2.5, 3.2, 32);
    const padMat = new THREE.MeshBasicMaterial({ color: 0x00f2fe, side: THREE.DoubleSide });
    const pad = new THREE.Mesh(padGeo, padMat);
    pad.rotation.x = -Math.PI / 2;
    pad.position.set(0, 0.04, 0);
    scene.add(pad);

    // 4. Build 3D Quadcopter Mesh
    const uav = new THREE.Group();
    uavGroupRef.current = uav;

    // Carbon Body Center
    const bodyGeo = new THREE.BoxGeometry(0.35, 0.08, 0.45);
    const bodyMat = new THREE.MeshStandardMaterial({ color: 0x1a2130, roughness: 0.3, metalness: 0.8 });
    const body = new THREE.Mesh(bodyGeo, bodyMat);
    uav.add(body);

    // Canopy / Top Dome
    const canopyGeo = new THREE.SphereGeometry(0.12, 16, 16);
    const canopyMat = new THREE.MeshStandardMaterial({ color: 0x00f2fe, roughness: 0.2, metalness: 0.9 });
    const canopy = new THREE.Mesh(canopyGeo, canopyMat);
    canopy.position.set(0, 0.06, -0.05);
    uav.add(canopy);

    // Arms & Rotors (Quad-X, 45 deg diagonals)
    const armGeo = new THREE.CylinderGeometry(0.015, 0.015, 0.45, 8);
    const armMat = new THREE.MeshStandardMaterial({ color: 0x111622 });
    const arm1 = new THREE.Mesh(armGeo, armMat);
    arm1.rotation.z = Math.PI / 2;
    arm1.rotation.y = Math.PI / 4;
    uav.add(arm1);

    const arm2 = new THREE.Mesh(armGeo, armMat);
    arm2.rotation.z = Math.PI / 2;
    arm2.rotation.y = -Math.PI / 4;
    uav.add(arm2);

    // 4 Motor canisters & Rotor blades
    const rotorOffsets = [
      { x: 0.22, z: -0.22 }, // M1 Front-Right
      { x: -0.22, z: 0.22 }, // M2 Rear-Left
      { x: -0.22, z: -0.22 },// M3 Front-Left
      { x: 0.22, z: 0.22 },  // M4 Rear-Right
    ];

    rotorMeshesRef.current = [];
    rotorOffsets.forEach((pos) => {
      // Motor mount
      const motorCan = new THREE.Mesh(
        new THREE.CylinderGeometry(0.03, 0.03, 0.04, 12),
        new THREE.MeshStandardMaterial({ color: 0x8899aa, metalness: 0.9 })
      );
      motorCan.position.set(pos.x, 0.03, pos.z);
      uav.add(motorCan);

      // Spinning rotor disc
      const rotorBlade = new THREE.Mesh(
        new THREE.BoxGeometry(0.24, 0.003, 0.02),
        new THREE.MeshStandardMaterial({ color: 0x00f2fe, transparent: true, opacity: 0.75 })
      );
      rotorBlade.position.set(pos.x, 0.06, pos.z);
      uav.add(rotorBlade);
      rotorMeshesRef.current.push(rotorBlade);
    });

    scene.add(uav);

    // 5. Flight Trajectory Ribbon
    const maxTrailPoints = 350;
    const trailGeo = new THREE.BufferGeometry();
    const trailPositions = new Float32Array(maxTrailPoints * 3);
    trailGeo.setAttribute('position', new THREE.BufferAttribute(trailPositions, 3));
    const trailMat = new THREE.LineBasicMaterial({ color: 0x00f5a0, linewidth: 2 });
    const trailLine = new THREE.Line(trailGeo, trailMat);
    trailLineRef.current = trailLine;
    scene.add(trailLine);

    // 6. Waypoints Group
    const wpGroup = new THREE.Group();
    waypointsGroupRef.current = wpGroup;
    scene.add(wpGroup);

    // Handle Resize
    const handleResize = () => {
      if (!container || !renderer || !camera) return;
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(container.clientWidth, container.clientHeight);
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
      if (container && renderer.domElement) {
        container.removeChild(renderer.domElement);
      }
    };
  }, []);

  // Update 3D Positions, Rotations & Camera each render frame
  useEffect(() => {
    const uav = uavGroupRef.current;
    const camera = cameraRef.current;
    const renderer = rendererRef.current;
    const scene = sceneRef.current;
    if (!uav || !camera || !renderer || !scene) return;

    // Update UAV World Position & Attitude
    uav.position.set(telemetry.position.x, telemetry.position.y + 0.05, telemetry.position.z);
    uav.rotation.order = 'YXZ';
    uav.rotation.y = telemetry.attitude.yaw;
    uav.rotation.x = telemetry.attitude.pitch;
    uav.rotation.z = -telemetry.attitude.roll;

    // Spin rotors proportional to RPM
    rotorMeshesRef.current.forEach((rotor, idx) => {
      const rpm = telemetry.motors[idx]?.rpm || 0;
      rotor.rotation.y += (rpm / 60) * 0.1;
    });

    // Update Trajectory trail
    if (trailLineRef.current && (telemetry.position.y > 0.1 || trailPointsRef.current.length > 0)) {
      trailPointsRef.current.push(new THREE.Vector3(telemetry.position.x, telemetry.position.y, telemetry.position.z));
      if (trailPointsRef.current.length > 350) {
        trailPointsRef.current.shift();
      }
      const posAttr = trailLineRef.current.geometry.getAttribute('position') as THREE.BufferAttribute;
      for (let i = 0; i < trailPointsRef.current.length; i++) {
        posAttr.setXYZ(i, trailPointsRef.current[i].x, trailPointsRef.current[i].y, trailPointsRef.current[i].z);
      }
      posAttr.needsUpdate = true;
      trailLineRef.current.geometry.setDrawRange(0, trailPointsRef.current.length);
    }

    // Camera Modes
    if (cameraMode === 'CHASE') {
      const offsetDist = 5.5;
      const offsetHeight = 2.4;
      const cy = Math.cos(telemetry.attitude.yaw);
      const sy = Math.sin(telemetry.attitude.yaw);
      const camTargetX = telemetry.position.x - sy * offsetDist;
      const camTargetZ = telemetry.position.z - cy * offsetDist;
      camera.position.lerp(new THREE.Vector3(camTargetX, telemetry.position.y + offsetHeight, camTargetZ), 0.1);
      camera.lookAt(telemetry.position.x, telemetry.position.y + 0.4, telemetry.position.z);
    } else if (cameraMode === 'FPV') {
      camera.position.set(telemetry.position.x, telemetry.position.y + 0.12, telemetry.position.z);
      camera.rotation.copy(uav.rotation);
    } else if (cameraMode === 'TACTICAL') {
      camera.position.set(telemetry.position.x, telemetry.position.y + 35, telemetry.position.z + 0.1);
      camera.lookAt(telemetry.position.x, 0, telemetry.position.z);
    } else if (cameraMode === 'GROUND') {
      camera.position.set(0, 1.6, -6);
      camera.lookAt(telemetry.position.x, telemetry.position.y, telemetry.position.z);
    }

    renderer.render(scene, camera);
  }, [telemetry, cameraMode]);

  return (
    <div className="tactical-panel" style={{ position: 'relative', width: '100%', height: '100%', minHeight: '380px' }}>
      <div ref={containerRef} style={{ width: '100%', height: '100%', borderRadius: '8px', overflow: 'hidden' }} />
      {/* Top Left Title Overlay */}
      <div style={{
        position: 'absolute',
        top: '12px',
        left: '14px',
        background: 'rgba(7, 9, 14, 0.75)',
        backdropFilter: 'blur(8px)',
        padding: '6px 12px',
        borderRadius: '6px',
        border: '1px solid var(--border-subtle)',
        fontSize: '11px',
        letterSpacing: '0.08em',
      }}>
        <span style={{ color: 'var(--accent-cyan)', fontWeight: 700 }}>3D FLIGHT ARENA</span> // LAT: {telemetry.sensors.gps.latitude.toFixed(5)} LON: {telemetry.sensors.gps.longitude.toFixed(5)}
      </div>

      {/* Camera Mode Buttons Overlay */}
      <div style={{
        position: 'absolute',
        top: '12px',
        right: '14px',
        display: 'flex',
        gap: '6px',
      }}>
        {(['CHASE', 'FPV', 'TACTICAL', 'GROUND'] as CameraMode[]).map((mode) => (
          <button
            key={mode}
            onClick={() => setCameraMode(mode)}
            className="tactical-btn"
            style={{
              minHeight: '28px',
              padding: '0 8px',
              fontSize: '11px',
              background: cameraMode === mode ? 'var(--accent-cyan)' : 'rgba(7, 9, 14, 0.8)',
              color: cameraMode === mode ? '#07090e' : 'var(--text-muted)',
              borderColor: cameraMode === mode ? 'var(--accent-cyan)' : 'var(--border-subtle)',
            }}
          >
            {mode}
          </button>
        ))}
      </div>
    </div>
  );
};

