import React from 'react';
import {
  Activity,
  ArrowUpRight,
  Gauge,
  Navigation,
  Radio,
  Wind,
  Zap,
} from 'lucide-react';
import { TelemetryPacket } from '../types/telemetry';

interface TelemetryStripProps {
  telemetry: TelemetryPacket;
  windSpeed: number;
  windHeading: number;
}

export const TelemetryStrip: React.FC<TelemetryStripProps> = ({
  telemetry,
  windSpeed,
  windHeading,
}) => {
  const agl = telemetry.sensors.barometer.altitudeAgl;
  const msl = telemetry.sensors.barometer.altitudeMsl;
  const vsi = telemetry.sensors.barometer.vsiMps;
  const airspeed = telemetry.sensors.airspeedMps;
  const groundSpeed = telemetry.sensors.gps.groundSpeedMps;
  const distHome = telemetry.distanceToHome;

  const ax = telemetry.sensors.imu.accel.x;
  const ay = telemetry.sensors.imu.accel.y;
  const az = telemetry.sensors.imu.accel.z;
  const gForce = Math.sqrt(ax * ax + ay * ay + az * az) / 9.80665;

  const cards = [
    {
      label: 'AIRSPEED',
      val: `${airspeed.toFixed(1)} m/s`,
      sub: `${(airspeed * 1.94384).toFixed(1)} kts`,
      icon: <Gauge size={16} color="var(--accent-cyan)" />,
      accent: 'var(--accent-cyan)',
    },
    {
      label: 'ALTITUDE AGL',
      val: `${agl.toFixed(1)} m`,
      sub: `MSL: ${msl.toFixed(1)}m`,
      icon: <ArrowUpRight size={16} color="var(--accent-emerald)" />,
      accent: 'var(--accent-emerald)',
    },
    {
      label: 'CLIMB RATE',
      val: `${vsi >= 0 ? '+' : ''}${vsi.toFixed(1)} m/s`,
      sub: `${(vsi * 196.85).toFixed(0)} ft/min`,
      icon: <Activity size={16} color={vsi >= 0 ? 'var(--accent-emerald)' : 'var(--accent-rose)'} />,
      accent: vsi >= 0 ? 'var(--accent-emerald)' : 'var(--accent-rose)',
    },
    {
      label: 'GROUND SPEED',
      val: `${groundSpeed.toFixed(1)} m/s`,
      sub: `DIST HOME: ${distHome.toFixed(1)}m`,
      icon: <Navigation size={16} color="var(--accent-blue)" />,
      accent: 'var(--accent-blue)',
    },
    {
      label: 'G-LOAD',
      val: `${gForce.toFixed(2)} G`,
      sub: `VIB: ${(telemetry.sensors.imu.vibrationLevel * 10).toFixed(2)}`,
      icon: <Zap size={16} color={gForce > 2.0 ? 'var(--accent-rose)' : 'var(--accent-amber)'} />,
      accent: gForce > 2.0 ? 'var(--accent-rose)' : 'var(--accent-amber)',
    },
    {
      label: 'WIND VECTOR',
      val: `${windSpeed.toFixed(1)} m/s`,
      sub: `HDG: ${windHeading.toFixed(0)}°`,
      icon: <Wind size={16} color="var(--text-muted)" />,
      accent: 'var(--text-muted)',
    },
    {
      label: 'RF LINK / RSSI',
      val: `-42 dBm`,
      sub: `100% LINK (LQ)`,
      icon: <Radio size={16} color="var(--accent-emerald)" />,
      accent: 'var(--accent-emerald)',
    },
  ];

  return (
    <div style={{
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(135px, 1fr))',
      gap: '8px',
      margin: '4px 8px',
    }}>
      {cards.map((c, i) => (
        <div
          key={i}
          className="tactical-panel"
          style={{
            padding: '8px 12px',
            borderLeft: `3px solid ${c.accent}`,
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '2px' }}>
            <span style={{ fontSize: '10px', color: 'var(--text-muted)', letterSpacing: '0.06em' }}>
              {c.label}
            </span>
            {c.icon}
          </div>
          <div style={{ fontSize: '16px', fontWeight: 700, color: '#fff', fontFamily: 'var(--font-mono)' }}>
            {c.val}
          </div>
          <div style={{ fontSize: '10px', color: 'var(--text-muted)' }}>
            {c.sub}
          </div>
        </div>
      ))}
    </div>
  );
};

