import React, { useEffect, useRef, useState } from 'react';
import { TelemetryPacket } from '../types/telemetry';

interface TelemetryGraphProps {
  telemetry: TelemetryPacket;
}

type GraphChannel = 'ATTITUDE' | 'MOTORS' | 'ALTITUDE' | 'ACCELEROMETER';

export const TelemetryGraph: React.FC<TelemetryGraphProps> = ({ telemetry }) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [channel, setChannel] = useState<GraphChannel>('ATTITUDE');
  const historyRef = useRef<{
    time: number;
    roll: number;
    pitch: number;
    yaw: number;
    m1: number;
    m2: number;
    m3: number;
    m4: number;
    alt: number;
    vsi: number;
    ax: number;
    ay: number;
    az: number;
  }[]>([]);

  useEffect(() => {
    historyRef.current.push({
      time: telemetry.timestamp,
      roll: (telemetry.attitude.roll * 180) / Math.PI,
      pitch: (telemetry.attitude.pitch * 180) / Math.PI,
      yaw: (telemetry.attitude.yaw * 180) / Math.PI,
      m1: telemetry.motors[0]?.rpm || 0,
      m2: telemetry.motors[1]?.rpm || 0,
      m3: telemetry.motors[2]?.rpm || 0,
      m4: telemetry.motors[3]?.rpm || 0,
      alt: telemetry.sensors.barometer.altitudeAgl,
      vsi: telemetry.sensors.barometer.vsiMps,
      ax: telemetry.sensors.imu.accel.x,
      ay: telemetry.sensors.imu.accel.y,
      az: telemetry.sensors.imu.accel.z,
    });

    if (historyRef.current.length > 120) {
      historyRef.current.shift();
    }

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // Draw background grid lines
    ctx.strokeStyle = 'rgba(0, 242, 254, 0.08)';
    ctx.lineWidth = 1;
    for (let x = 0; x < w; x += 30) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = 0; y < h; y += 25) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }

    // Zero / Center reference line
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(0, h / 2);
    ctx.lineTo(w, h / 2);
    ctx.stroke();
    ctx.setLineDash([]);

    const data = historyRef.current;
    if (data.length < 2) return;

    const drawSeries = (
      getValue: (d: (typeof data)[0]) => number,
      color: string,
      scaleMin: number,
      scaleMax: number
    ) => {
      ctx.strokeStyle = color;
      ctx.lineWidth = 2;
      ctx.beginPath();
      for (let i = 0; i < data.length; i++) {
        const x = (i / (data.length - 1)) * w;
        const val = getValue(data[i]);
        const norm = (val - scaleMin) / (scaleMax - scaleMin);
        const y = h - norm * h;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    };

    if (channel === 'ATTITUDE') {
      drawSeries((d) => d.roll, '#00f2fe', -35, 35);
      drawSeries((d) => d.pitch, '#f6d365', -35, 35);
      drawSeries((d) => d.yaw % 360, '#00f5a0', 0, 360);
    } else if (channel === 'MOTORS') {
      drawSeries((d) => d.m1, '#00f2fe', 0, 18000);
      drawSeries((d) => d.m2, '#4facfe', 0, 18000);
      drawSeries((d) => d.m3, '#f6d365', 0, 18000);
      drawSeries((d) => d.m4, '#ff416c', 0, 18000);
    } else if (channel === 'ALTITUDE') {
      drawSeries((d) => d.alt, '#00f5a0', 0, 30);
      drawSeries((d) => d.vsi, '#00f2fe', -4, 4);
    } else if (channel === 'ACCELEROMETER') {
      drawSeries((d) => d.ax, '#00f2fe', -15, 15);
      drawSeries((d) => d.ay, '#00f5a0', -15, 25);
      drawSeries((d) => d.az, '#ff416c', -15, 15);
    }
  }, [telemetry, channel]);

  return (
    <div className="tactical-panel" style={{ padding: '10px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
        <span className="tactical-title" style={{ fontSize: '13px', color: 'var(--accent-cyan)' }}>
          TELEMETRY OSCILLOSCOPE
        </span>
        <div style={{ display: 'flex', gap: '4px' }}>
          {(['ATTITUDE', 'MOTORS', 'ALTITUDE', 'ACCELEROMETER'] as GraphChannel[]).map((c) => (
            <button
              key={c}
              onClick={() => setChannel(c)}
              className="tactical-btn"
              style={{
                minHeight: '24px',
                padding: '0 8px',
                fontSize: '10px',
                background: channel === c ? 'rgba(0, 242, 254, 0.25)' : 'transparent',
                borderColor: channel === c ? 'var(--accent-cyan)' : 'var(--border-subtle)',
                color: channel === c ? 'var(--accent-cyan)' : 'var(--text-muted)',
              }}
            >
              {c}
            </button>
          ))}
        </div>
      </div>
      <canvas
        ref={canvasRef}
        width={380}
        height={130}
        style={{ width: '100%', height: '130px', background: '#05070a', borderRadius: '4px', display: 'block' }}
      />
      {/* Legend */}
      <div style={{ display: 'flex', gap: '14px', marginTop: '6px', fontSize: '10px', color: 'var(--text-muted)' }}>
        {channel === 'ATTITUDE' && (
          <>
            <span style={{ color: '#00f2fe' }}>■ Roll (±35°)</span>
            <span style={{ color: '#f6d365' }}>■ Pitch (±35°)</span>
            <span style={{ color: '#00f5a0' }}>■ Yaw (0-360°)</span>
          </>
        )}
        {channel === 'MOTORS' && (
          <>
            <span style={{ color: '#00f2fe' }}>■ M1 Front-R</span>
            <span style={{ color: '#4facfe' }}>■ M2 Rear-L</span>
            <span style={{ color: '#f6d365' }}>■ M3 Front-L</span>
            <span style={{ color: '#ff416c' }}>■ M4 Rear-R</span>
          </>
        )}
        {channel === 'ALTITUDE' && (
          <>
            <span style={{ color: '#00f5a0' }}>■ Alt AGL (0-30m)</span>
            <span style={{ color: '#00f2fe' }}>■ VSI (±4m/s)</span>
          </>
        )}
        {channel === 'ACCELEROMETER' && (
          <>
            <span style={{ color: '#00f2fe' }}>■ Acc X</span>
            <span style={{ color: '#00f5a0' }}>■ Acc Y</span>
            <span style={{ color: '#ff416c' }}>■ Acc Z</span>
          </>
        )}
      </div>
    </div>
  );
};

