import React, { useEffect, useRef, useState } from 'react';
import { Play, RotateCw, UploadCloud } from 'lucide-react';
import { PRESET_FLIGHT_PLANS } from '../services/missionPresets';
import { FlightPlan, Waypoint } from '../types/mission';
import { TelemetryPacket } from '../types/telemetry';

interface MissionPlannerProps {
  telemetry: TelemetryPacket;
  activeWaypoints: Waypoint[];
  activeWpIndex: number;
  onUploadMission: (waypoints: Waypoint[]) => void;
  onClearMission: () => void;
}

export const MissionPlanner: React.FC<MissionPlannerProps> = ({
  telemetry,
  activeWaypoints,
  activeWpIndex,
  onUploadMission,
  onClearMission,
}) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [selectedPlanId, setSelectedPlanId] = useState<string>(PRESET_FLIGHT_PLANS[0].id);

  const handleLoadPreset = () => {
    const plan = PRESET_FLIGHT_PLANS.find((p) => p.id === selectedPlanId);
    if (plan) {
      onUploadMission(plan.waypoints);
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const w = canvas.width;
    const h = canvas.height;
    const cx = w / 2;
    const cy = h / 2;
    const scale = 2.4; // pixels per meter (covers ~100m radius)

    ctx.clearRect(0, 0, w, h);

    // 1. Radar Range Rings (15m, 30m, 50m)
    const ranges = [15, 30, 50];
    ctx.lineWidth = 1;
    ranges.forEach((r) => {
      ctx.strokeStyle = 'rgba(0, 242, 254, 0.15)';
      ctx.beginPath();
      ctx.arc(cx, cy, r * scale, 0, Math.PI * 2);
      ctx.stroke();

      ctx.fillStyle = 'rgba(0, 242, 254, 0.4)';
      ctx.font = '8px "JetBrains Mono"';
      ctx.fillText(`${r}m`, cx + r * scale - 12, cy - 3);
    });

    // 2. Geofence Boundary (60m)
    ctx.strokeStyle = 'rgba(246, 211, 101, 0.5)';
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.arc(cx, cy, 60 * scale, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // 3. Home point marker
    ctx.fillStyle = '#00f2fe';
    ctx.beginPath();
    ctx.arc(cx, cy, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'var(--text-muted)';
    ctx.font = '9px "JetBrains Mono"';
    ctx.fillText('HOME', cx + 6, cy + 3);

    // 4. Draw Waypoint flight path
    if (activeWaypoints.length > 0) {
      ctx.strokeStyle = 'rgba(0, 245, 160, 0.6)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      activeWaypoints.forEach((wp, idx) => {
        const wx = cx + wp.position.x * scale;
        const wy = cy + wp.position.z * scale;
        if (idx === 0) ctx.moveTo(wx, wy);
        else ctx.lineTo(wx, wy);
      });
      ctx.stroke();

      // Waypoint nodes
      activeWaypoints.forEach((wp, idx) => {
        const wx = cx + wp.position.x * scale;
        const wy = cy + wp.position.z * scale;
        const isCurrent = idx === activeWpIndex;

        ctx.fillStyle = isCurrent ? '#00f2fe' : '#00f5a0';
        ctx.beginPath();
        ctx.arc(wx, wy, isCurrent ? 6 : 4, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#fff';
        ctx.font = '9px "JetBrains Mono"';
        ctx.fillText(`WP${idx + 1} (${wp.position.y}m)`, wx + 6, wy - 3);
      });
    }

    // 5. Draw UAV Position & Heading Arrow
    const ux = cx + telemetry.position.x * scale;
    const uy = cy + telemetry.position.z * scale;

    ctx.save();
    ctx.translate(ux, uy);
    ctx.rotate(telemetry.attitude.yaw);

    // UAV triangular icon
    ctx.fillStyle = '#f6d365';
    ctx.beginPath();
    ctx.moveTo(0, -8);
    ctx.lineTo(6, 6);
    ctx.lineTo(0, 3);
    ctx.lineTo(-6, 6);
    ctx.closePath();
    ctx.fill();

    ctx.restore();
  }, [telemetry, activeWaypoints, activeWpIndex]);

  return (
    <div className="tactical-panel" style={{ padding: '10px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
        <span className="tactical-title" style={{ fontSize: '13px', color: 'var(--accent-cyan)' }}>
          TACTICAL RADAR & MISSION PLANNER
        </span>
        <span style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
          WP: <span style={{ color: '#fff', fontWeight: 700 }}>{activeWpIndex + 1}/{Math.max(1, activeWaypoints.length)}</span>
        </span>
      </div>

      <canvas
        ref={canvasRef}
        width={360}
        height={210}
        style={{ width: '100%', height: '210px', background: '#05070a', borderRadius: '4px', display: 'block' }}
      />

      {/* Preset Selector & Action Buttons */}
      <div style={{ display: 'flex', gap: '8px', marginTop: '8px' }}>
        <select
          value={selectedPlanId}
          onChange={(e) => setSelectedPlanId(e.target.value)}
          style={{
            flex: 1,
            background: 'rgba(7, 9, 14, 0.8)',
            border: '1px solid var(--border-subtle)',
            borderRadius: '4px',
            color: '#fff',
            fontSize: '11px',
            padding: '4px 8px',
            fontFamily: 'var(--font-mono)',
          }}
        >
          {PRESET_FLIGHT_PLANS.map((p) => (
            <option key={p.id} value={p.id}>
              {p.name} ({p.waypoints.length} WPs)
            </option>
          ))}
        </select>

        <button
          onClick={handleLoadPreset}
          className="tactical-btn tactical-btn-primary"
          style={{ minHeight: '30px', padding: '0 10px', fontSize: '11px' }}
          title="Upload Waypoints to Flight Computer"
        >
          <UploadCloud size={14} />
          <span>UPLOAD</span>
        </button>

        <button
          onClick={onClearMission}
          className="tactical-btn"
          style={{ minHeight: '30px', padding: '0 8px', fontSize: '11px' }}
          title="Clear Active Waypoints"
        >
          <RotateCw size={14} />
        </button>
      </div>
    </div>
  );
};

