import React, { useState } from 'react';
import {
  CheckCircle2,
  FileText,
  Play,
  RotateCcw,
  ShieldCheck,
  XCircle,
} from 'lucide-react';
import { FlightTestReport, TestScenario } from '../types/testSuite';

interface TestFlightSuiteProps {
  scenarios: TestScenario[];
  activeScenario: TestScenario | null;
  onStartScenario: (id: string) => void;
  onGenerateReport: () => FlightTestReport;
}

export const TestFlightSuite: React.FC<TestFlightSuiteProps> = ({
  scenarios,
  activeScenario,
  onStartScenario,
  onGenerateReport,
}) => {
  const [report, setReport] = useState<FlightTestReport | null>(null);

  const handleOpenReport = () => {
    const rep = onGenerateReport();
    setReport(rep);
  };

  return (
    <div className="tactical-panel" style={{ padding: '12px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <ShieldCheck size={18} color="var(--accent-cyan)" />
          <span className="tactical-title" style={{ fontSize: '13px', color: 'var(--accent-cyan)' }}>
            FLIGHT ACCEPTANCE TEST (FAT) SUITE
          </span>
        </div>
        <button
          onClick={handleOpenReport}
          className="tactical-btn tactical-btn-primary"
          style={{ minHeight: '28px', padding: '0 10px', fontSize: '11px' }}
        >
          <FileText size={14} />
          <span>VIEW REPORT</span>
        </button>
      </div>

      {/* Scenario Cards */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', maxHeight: '280px', overflowY: 'auto' }}>
        {scenarios.map((s) => {
          const isRunning = activeScenario?.id === s.id;
          return (
            <div
              key={s.id}
              style={{
                background: 'rgba(7, 9, 14, 0.6)',
                border: isRunning ? '1px solid var(--accent-cyan)' : '1px solid var(--border-subtle)',
                borderRadius: '6px',
                padding: '8px 12px',
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '4px' }}>
                <div>
                  <span style={{ fontSize: '10px', color: 'var(--accent-blue)', fontWeight: 700, marginRight: '6px' }}>
                    [{s.id}]
                  </span>
                  <span style={{ fontSize: '12px', fontWeight: 600, color: '#fff' }}>
                    {s.name}
                  </span>
                </div>
                {/* Status Badge */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                  {s.status === 'PASSED' && <CheckCircle2 size={16} color="var(--accent-emerald)" />}
                  {s.status === 'FAILED' && <XCircle size={16} color="var(--accent-rose)" />}
                  {s.status === 'RUNNING' && (
                    <span style={{ fontSize: '10px', color: 'var(--accent-cyan)', fontWeight: 700 }}>
                      {s.progressPercent.toFixed(0)}%
                    </span>
                  )}
                  <button
                    onClick={() => onStartScenario(s.id)}
                    disabled={isRunning}
                    className="tactical-btn"
                    style={{
                      minHeight: '24px',
                      padding: '0 8px',
                      fontSize: '10px',
                      background: isRunning ? 'var(--accent-cyan)' : 'rgba(0, 242, 254, 0.1)',
                      color: isRunning ? '#07090e' : 'var(--accent-cyan)',
                      borderColor: 'var(--border-subtle)',
                    }}
                  >
                    <Play size={10} />
                    <span>{isRunning ? 'TESTING...' : 'RUN'}</span>
                  </button>
                </div>
              </div>

              <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '6px' }}>
                {s.description}
              </div>

              {/* Live Criteria list */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: '6px' }}>
                {s.criteria.map((c) => (
                  <div
                    key={c.id}
                    style={{
                      background: 'rgba(0, 0, 0, 0.3)',
                      padding: '4px 6px',
                      borderRadius: '4px',
                      fontSize: '10px',
                      display: 'flex',
                      justifyContent: 'space-between',
                      borderLeft: c.passed ? '2px solid var(--accent-emerald)' : '2px solid var(--border-subtle)',
                    }}
                  >
                    <span style={{ color: 'var(--text-muted)' }}>{c.name}:</span>
                    <span style={{ fontWeight: 600, color: c.passed ? 'var(--accent-emerald)' : '#fff' }}>
                      {c.measured.toFixed(2)} {c.unit} (tgt: {c.target})
                    </span>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {/* Report Modal */}
      {report && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0, 0, 0, 0.85)',
          backdropFilter: 'blur(8px)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000,
        }}>
          <div className="tactical-panel" style={{ width: '560px', padding: '24px', maxHeight: '90vh', overflowY: 'auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
              <div>
                <h2 style={{ fontSize: '18px', fontWeight: 700, color: 'var(--accent-cyan)' }}>
                  FLIGHT ACCEPTANCE TEST (FAT) REPORT
                </h2>
                <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
                  CERTIFICATE ID: {report.id} | AIRCRAFT: {report.aircraftSerial}
                </div>
              </div>
              <button onClick={() => setReport(null)} className="tactical-btn" style={{ minHeight: '30px', padding: '0 12px' }}>
                CLOSE
              </button>
            </div>

            <div style={{
              display: 'grid',
              gridTemplateColumns: '1fr 1fr 1fr',
              gap: '10px',
              marginBottom: '16px',
              background: 'rgba(0, 242, 254, 0.05)',
              padding: '12px',
              borderRadius: '6px',
              border: '1px solid var(--border-subtle)',
            }}>
              <div>
                <div style={{ fontSize: '10px', color: 'var(--text-muted)' }}>OVERALL SCORE</div>
                <div style={{ fontSize: '22px', fontWeight: 800, color: report.overallScore >= 80 ? 'var(--accent-emerald)' : 'var(--accent-rose)' }}>
                  {report.overallScore} / 100
                </div>
              </div>
              <div>
                <div style={{ fontSize: '10px', color: 'var(--text-muted)' }}>PASSED SCENARIOS</div>
                <div style={{ fontSize: '22px', fontWeight: 800, color: '#fff' }}>
                  {report.passedScenarios} / {report.totalScenarios}
                </div>
              </div>
              <div>
                <div style={{ fontSize: '10px', color: 'var(--text-muted)' }}>TEST RESULT</div>
                <div style={{ fontSize: '16px', fontWeight: 800, color: report.passedScenarios === report.totalScenarios ? 'var(--accent-emerald)' : 'var(--accent-amber)' }}>
                  {report.passedScenarios === report.totalScenarios ? 'ACCEPTED' : 'PROVISIONAL'}
                </div>
              </div>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {report.scenarios.map((s) => (
                <div key={s.id} style={{ background: 'rgba(7, 9, 14, 0.8)', padding: '8px 12px', borderRadius: '4px', border: '1px solid var(--border-subtle)' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontSize: '12px', fontWeight: 700, color: '#fff' }}>{s.name}</span>
                    <span style={{ fontSize: '11px', fontWeight: 700, color: s.status === 'PASSED' ? 'var(--accent-emerald)' : 'var(--accent-rose)' }}>
                      {s.status}
                    </span>
                  </div>
                  <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginTop: '4px' }}>
                    {s.summaryNote || 'Criteria verified within nominal parameters.'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

