import React, { useState } from 'react';
import { RotateCcw, Sliders, Zap } from 'lucide-react';
import { UAVPIDConfig } from '../types/controls';

interface PidTuningPanelProps {
  pidConfig: UAVPIDConfig;
  onUpdatePid: (config: UAVPIDConfig) => void;
  onInjectImpulse: (axis: 'roll' | 'pitch' | 'yaw') => void;
}

export const PidTuningPanel: React.FC<PidTuningPanelProps> = ({
  pidConfig,
  onUpdatePid,
  onInjectImpulse,
}) => {
  const [activeTab, setActiveTab] = useState<'ATTITUDE' | 'RATE' | 'ALTITUDE'>('RATE');

  const updateGain = (
    loop: keyof UAVPIDConfig,
    field: 'kp' | 'ki' | 'kd',
    value: number
  ) => {
    const updated = JSON.parse(JSON.stringify(pidConfig)) as UAVPIDConfig;
    updated[loop][field] = value;
    onUpdatePid(updated);
  };

  const applyPreset = (preset: 'BALANCED' | 'ACRO' | 'CINEMATIC' | 'WIND') => {
    const cfg = JSON.parse(JSON.stringify(pidConfig)) as UAVPIDConfig;
    if (preset === 'BALANCED') {
      cfg.rollRate.kp = 0.14; cfg.rollRate.ki = 0.08; cfg.rollRate.kd = 0.003;
      cfg.pitchRate.kp = 0.14; cfg.pitchRate.ki = 0.08; cfg.pitchRate.kd = 0.003;
    } else if (preset === 'ACRO') {
      cfg.rollRate.kp = 0.22; cfg.rollRate.ki = 0.12; cfg.rollRate.kd = 0.005;
      cfg.pitchRate.kp = 0.22; cfg.pitchRate.ki = 0.12; cfg.pitchRate.kd = 0.005;
    } else if (preset === 'CINEMATIC') {
      cfg.rollRate.kp = 0.09; cfg.rollRate.ki = 0.05; cfg.rollRate.kd = 0.002;
      cfg.pitchRate.kp = 0.09; cfg.pitchRate.ki = 0.05; cfg.pitchRate.kd = 0.002;
    } else if (preset === 'WIND') {
      cfg.rollRate.kp = 0.18; cfg.rollRate.ki = 0.15; cfg.rollRate.kd = 0.004;
      cfg.pitchRate.kp = 0.18; cfg.pitchRate.ki = 0.15; cfg.pitchRate.kd = 0.004;
    }
    onUpdatePid(cfg);
  };

  return (
    <div className="tactical-panel" style={{ padding: '10px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <Sliders size={16} color="var(--accent-cyan)" />
          <span className="tactical-title" style={{ fontSize: '13px', color: 'var(--accent-cyan)' }}>
            PID FLIGHT CONTROLLER TUNING
          </span>
        </div>
        {/* Preset Selector */}
        <div style={{ display: 'flex', gap: '4px' }}>
          {(['BALANCED', 'ACRO', 'CINEMATIC', 'WIND'] as const).map((p) => (
            <button
              key={p}
              onClick={() => applyPreset(p)}
              className="tactical-btn"
              style={{ minHeight: '22px', padding: '0 6px', fontSize: '9px' }}
            >
              {p}
            </button>
          ))}
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '6px', marginBottom: '8px' }}>
        {(['RATE', 'ATTITUDE', 'ALTITUDE'] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className="tactical-btn"
            style={{
              flex: 1,
              minHeight: '26px',
              fontSize: '11px',
              background: activeTab === tab ? 'rgba(0, 242, 254, 0.2)' : 'transparent',
              borderColor: activeTab === tab ? 'var(--accent-cyan)' : 'var(--border-subtle)',
              color: activeTab === tab ? 'var(--accent-cyan)' : 'var(--text-muted)',
            }}
          >
            {tab} LOOP
          </button>
        ))}
      </div>

      {/* Sliders Area */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', background: 'rgba(7, 9, 14, 0.6)', padding: '10px', borderRadius: '4px' }}>
        {activeTab === 'RATE' && (
          <>
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', marginBottom: '2px' }}>
                <span style={{ color: '#fff' }}>Roll/Pitch Rate Kp</span>
                <span style={{ color: 'var(--accent-cyan)' }}>{pidConfig.rollRate.kp.toFixed(3)}</span>
              </div>
              <input
                type="range"
                min="0.02"
                max="0.4"
                step="0.005"
                value={pidConfig.rollRate.kp}
                onChange={(e) => {
                  updateGain('rollRate', 'kp', parseFloat(e.target.value));
                  updateGain('pitchRate', 'kp', parseFloat(e.target.value));
                }}
                style={{ width: '100%', accentColor: 'var(--accent-cyan)' }}
              />
            </div>
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', marginBottom: '2px' }}>
                <span style={{ color: '#fff' }}>Roll/Pitch Rate Ki</span>
                <span style={{ color: 'var(--accent-blue)' }}>{pidConfig.rollRate.ki.toFixed(3)}</span>
              </div>
              <input
                type="range"
                min="0.0"
                max="0.3"
                step="0.005"
                value={pidConfig.rollRate.ki}
                onChange={(e) => {
                  updateGain('rollRate', 'ki', parseFloat(e.target.value));
                  updateGain('pitchRate', 'ki', parseFloat(e.target.value));
                }}
                style={{ width: '100%', accentColor: 'var(--accent-blue)' }}
              />
            </div>
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', marginBottom: '2px' }}>
                <span style={{ color: '#fff' }}>Roll/Pitch Rate Kd</span>
                <span style={{ color: 'var(--accent-amber)' }}>{pidConfig.rollRate.kd.toFixed(4)}</span>
              </div>
              <input
                type="range"
                min="0.0"
                max="0.015"
                step="0.0005"
                value={pidConfig.rollRate.kd}
                onChange={(e) => {
                  updateGain('rollRate', 'kd', parseFloat(e.target.value));
                  updateGain('pitchRate', 'kd', parseFloat(e.target.value));
                }}
                style={{ width: '100%', accentColor: 'var(--accent-amber)' }}
              />
            </div>
          </>
        )}

        {activeTab === 'ATTITUDE' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', marginBottom: '2px' }}>
              <span style={{ color: '#fff' }}>Bank Angle Angle Kp</span>
              <span style={{ color: 'var(--accent-cyan)' }}>{pidConfig.rollAngle.kp.toFixed(1)}</span>
            </div>
            <input
              type="range"
              min="1.0"
              max="9.0"
              step="0.2"
              value={pidConfig.rollAngle.kp}
              onChange={(e) => {
                updateGain('rollAngle', 'kp', parseFloat(e.target.value));
                updateGain('pitchAngle', 'kp', parseFloat(e.target.value));
              }}
              style={{ width: '100%', accentColor: 'var(--accent-cyan)' }}
            />
          </div>
        )}

        {activeTab === 'ALTITUDE' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', marginBottom: '2px' }}>
              <span style={{ color: '#fff' }}>Altitude Hold Kp</span>
              <span style={{ color: 'var(--accent-emerald)' }}>{pidConfig.altitude.kp.toFixed(2)}</span>
            </div>
            <input
              type="range"
              min="0.2"
              max="3.0"
              step="0.05"
              value={pidConfig.altitude.kp}
              onChange={(e) => updateGain('altitude', 'kp', parseFloat(e.target.value))}
              style={{ width: '100%', accentColor: 'var(--accent-emerald)' }}
            />
          </div>
        )}

        {/* Step Impulse Injection */}
        <div style={{ display: 'flex', gap: '6px', marginTop: '4px' }}>
          <button
            onClick={() => onInjectImpulse('roll')}
            className="tactical-btn"
            style={{ flex: 1, minHeight: '26px', fontSize: '10px' }}
          >
            <Zap size={10} />
            <span>TEST ROLL STEP</span>
          </button>
          <button
            onClick={() => onInjectImpulse('pitch')}
            className="tactical-btn"
            style={{ flex: 1, minHeight: '26px', fontSize: '10px' }}
          >
            <Zap size={10} />
            <span>TEST PITCH STEP</span>
          </button>
        </div>
      </div>
    </div>
  );
};

