import React, { useEffect, useRef } from 'react';
import { Gamepad2, Keyboard } from 'lucide-react';
import { PilotInput } from '../types/controls';

interface ManualControlsProps {
  pilotInput: PilotInput;
  onChangeInput: (input: Partial<PilotInput>) => void;
}

export const ManualControls: React.FC<ManualControlsProps> = ({
  pilotInput,
  onChangeInput,
}) => {
  // Virtual Stick Gimbals
  const leftStickRef = useRef<HTMLDivElement | null>(null);
  const rightStickRef = useRef<HTMLDivElement | null>(null);

  // Keyboard controls listener
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'KeyW', 'KeyS', 'KeyA', 'KeyD', 'Space'].includes(e.code)) {
        e.preventDefault();
      }

      if (e.code === 'KeyW') onChangeInput({ throttle: Math.min(1.0, pilotInput.throttle + 0.05) });
      if (e.code === 'KeyS') onChangeInput({ throttle: Math.max(0.0, pilotInput.throttle - 0.05) });
      if (e.code === 'KeyA') onChangeInput({ yaw: -0.6 });
      if (e.code === 'KeyD') onChangeInput({ yaw: 0.6 });
      if (e.code === 'ArrowUp') onChangeInput({ pitch: -0.5 });
      if (e.code === 'ArrowDown') onChangeInput({ pitch: 0.5 });
      if (e.code === 'ArrowLeft') onChangeInput({ roll: -0.5 });
      if (e.code === 'ArrowRight') onChangeInput({ roll: 0.5 });
      if (e.code === 'Space') onChangeInput({ roll: 0, pitch: 0, yaw: 0 });
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'KeyA' || e.code === 'KeyD') onChangeInput({ yaw: 0 });
      if (e.code === 'ArrowUp' || e.code === 'ArrowDown') onChangeInput({ pitch: 0 });
      if (e.code === 'ArrowLeft' || e.code === 'ArrowRight') onChangeInput({ roll: 0 });
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [pilotInput, onChangeInput]);

  return (
    <div className="tactical-panel" style={{ padding: '10px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <Gamepad2 size={16} color="var(--accent-cyan)" />
          <span className="tactical-title" style={{ fontSize: '13px', color: 'var(--accent-cyan)' }}>
            MANUAL RC FLIGHT GIMBALS
          </span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '10px', color: 'var(--text-muted)' }}>
