            <div
              style={{
                width: '24px',
                height: '24px',
                borderRadius: '50%',
                background: 'var(--accent-cyan)',
                position: 'absolute',
                top: `${(1 - pilotInput.throttle) * 66}px`,
                left: `${(pilotInput.yaw + 1) * 33}px`,
                boxShadow: '0 0 10px rgba(0, 242, 254, 0.7)',
                transition: 'all 0.05s ease',
              }}
            />
          </div>
          <div style={{ fontSize: '10px', color: 'var(--text-muted)', marginTop: '4px' }}>
            THR: {(pilotInput.throttle * 100).toFixed(0)}% | YAW: {(pilotInput.yaw * 100).toFixed(0)}%
