                borderRadius: '50%',
                background: 'var(--accent-amber)',
                position: 'absolute',
                top: `${(pilotInput.pitch + 1) * 33}px`,
                left: `${(pilotInput.roll + 1) * 33}px`,
                boxShadow: '0 0 10px rgba(246, 211, 101, 0.7)',
