import React from 'react';
import { Download, Film, Pause, Play, Trash2 } from 'lucide-react';
import { flightRecorder } from '../services/flightRecorder';

interface BlackboxPlaybackProps {
  frameCount: number;
  isReplaying: boolean;
  replayIndex: number;
  onToggleReplay: () => void;
  onScrub: (index: number) => void;
  onClear: () => void;
}

export const BlackboxPlayback: React.FC<BlackboxPlaybackProps> = ({
  frameCount,
  isReplaying,
  replayIndex,
  onToggleReplay,
  onScrub,
  onClear,
}) => {
  const handleExport = () => {
    flightRecorder.downloadCSV();
  };

  const elapsedRecordedSec = (frameCount * 0.05).toFixed(1);

  return (
    <div className="tactical-panel" style={{ padding: '10px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
