import React, { useEffect, useRef, useState } from 'react';
import { BlackboxPlayback } from './components/BlackboxPlayback';
import { Header } from './components/Header';
import { ManualControls } from './components/ManualControls';
import { MissionPlanner } from './components/MissionPlanner';
import { PidTuningPanel } from './components/PidTuningPanel';
import { PrimaryFlightDisplay } from './components/PrimaryFlightDisplay';
import { TelemetryGraph } from './components/TelemetryGraph';
import { TelemetryStrip } from './components/TelemetryStrip';
import { TestFlightSuite } from './components/TestFlightSuite';
import { Viewport3D } from './components/Viewport3D';
import { AutopilotEngine } from './engine/autopilot';
import { EnvironmentEngine } from './engine/environment';
import { PhysicsEngine } from './engine/physicsEngine';
import { SensorEngine } from './engine/sensors';
import { TestScenarioRunner } from './engine/testScenarioRunner';
import { flightRecorder } from './services/flightRecorder';
import { PRESET_FLIGHT_PLANS } from './services/missionPresets';
import { soundEngine } from './services/soundEngine';
import { PilotInput, UAVPIDConfig } from './types/controls';
import { Waypoint } from './types/mission';
import { ArmState, FlightMode, TelemetryPacket } from './types/telemetry';

export const App: React.FC = () => {
  // Engine Instances
  const physicsRef = useRef(new PhysicsEngine());
  const autopilotRef = useRef(new AutopilotEngine());
  const envRef = useRef(new EnvironmentEngine());
  const sensorsRef = useRef(new SensorEngine());
  const testRunnerRef = useRef(new TestScenarioRunner());

  // React State for UI Telemetry (updated at 30-60Hz)
  const [telemetry, setTelemetry] = useState<TelemetryPacket>(() => {
    const p = physicsRef.current.getState();
    const s = sensorsRef.current.update(p, 0);
    return {
      timestamp: 0,
      armState: 'DISARMED',
      flightMode: 'DISARMED',
      position: p.position,
      velocity: p.velocity,
      attitude: p.attitude,
      sensors: s,
      motors: p.motors,
      battery: p.battery,
      activeWaypointIndex: 0,
      distanceToHome: 0,
      distanceToWaypoint: 0,
      warnings: [],
    };
  });

  const [pilotInput, setPilotInput] = useState<PilotInput>({ throttle: 0.5, roll: 0, pitch: 0, yaw: 0 });
  const [isAudioMuted, setIsAudioMuted] = useState(true);
  const [rightPanelTab, setRightPanelTab] = useState<'MISSION' | 'FAT_SUITE' | 'PID_TUNER'>('FAT_SUITE');
  const [waypoints, setWaypoints] = useState<Waypoint[]>(PRESET_FLIGHT_PLANS[0].waypoints);
  const [frameCount, setFrameCount] = useState(0);
  const [isReplaying, setIsReplaying] = useState(false);
  const [replayIndex, setReplayIndex] = useState(0);

  // Initialize autopilot waypoints
  useEffect(() => {
    autopilotRef.current.waypoints = waypoints;
  }, [waypoints]);

  // Main Simulation Loop (60Hz)
  useEffect(() => {
    let animId: number;
    let lastTime = performance.now();

    const loop = (now: number) => {
      const dt = Math.min(0.033, (now - lastTime) / 1000);
      lastTime = now;

      const physics = physicsRef.current;
      const autopilot = autopilotRef.current;
      const env = envRef.current;
      const sensors = sensorsRef.current;
      const runner = testRunnerRef.current;

      if (!isReplaying) {
        // 1. Environment Step
        const envState = env.update(dt, physics.getState().position.y);

        // 2. Autopilot Computation
        const motorOutputs = autopilot.computeMotorOutputs(physics.getState(), dt, pilotInput);
        for (let i = 0; i < 4; i++) {
          physics.setMotorThrottle(i, motorOutputs[i]);
        }

        // 3. Physics Step
        const uavState = physics.step(dt, envState.windVector, envState.airDensity);

        // 4. Sensors Step
        const sensorData = sensors.update(uavState, Math.sqrt(uavState.velocity.x * uavState.velocity.x + uavState.velocity.z * uavState.velocity.z));

        // 5. Test Runner Step
        runner.update(dt, uavState, physics, autopilot, env);

        // 6. Sound Engine Update
        const avgRpm = uavState.motors.reduce((acc, m) => acc + m.rpm, 0) / 4;
        soundEngine.update(avgRpm, sensorData.airspeedMps);

        // 7. Distance & Warnings Calculation
        const distHome = Math.sqrt(uavState.position.x * uavState.position.x + uavState.position.z * uavState.position.z);
        const warnings: string[] = [];
        if (uavState.battery.percent < 20) warnings.push('BATTERY CRITICAL');
        if (distHome > 60) warnings.push('GEOFENCE BREACH');
        if (uavState.hasCrashed) warnings.push('AIRCRAFT CRASH DETECTED');

        const packet: TelemetryPacket = {
          timestamp: uavState.timestamp,
          armState: autopilot.armState,
          flightMode: autopilot.flightMode,
          position: { ...uavState.position },
          velocity: { ...uavState.velocity },
          attitude: { ...uavState.attitude },
          sensors: sensorData,
          motors: uavState.motors.map((m) => ({ ...m })),
          battery: { ...uavState.battery },
          activeWaypointIndex: autopilot.activeWaypointIndex,
          distanceToHome: distHome,
          distanceToWaypoint: 0,
          warnings,
        };

        // Record Telemetry
        flightRecorder.addFrame(packet);
        setFrameCount(flightRecorder.getFrameCount());
        setTelemetry(packet);
      } else {
        // Replay Mode
        const frame = flightRecorder.getFrameAt(replayIndex);
        if (frame) {
          setTelemetry(frame);
          setReplayIndex((prev) => (prev < flightRecorder.getFrameCount() - 1 ? prev + 1 : 0));
        }
      }

      animId = requestAnimationFrame(loop);
    };

    animId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animId);
  }, [isReplaying, replayIndex, pilotInput]);

  // Handlers
  const handleToggleArm = () => {
    const nextState: ArmState = autopilotRef.current.armState === 'ARMED' ? 'DISARMED' : 'ARMED';
    autopilotRef.current.setArmState(nextState);
    if (nextState === 'ARMED') {
      autopilotRef.current.setFlightMode('ALT_HOLD');
      autopilotRef.current.targetPosition.y = 5.0; // Auto climb to 5m hover
    }
  };

  const handleSelectFlightMode = (mode: FlightMode) => {
    autopilotRef.current.setFlightMode(mode);
    if (mode === 'ALT_HOLD' || mode === 'POS_HOLD') {
      autopilotRef.current.targetPosition = { ...physicsRef.current.getState().position };
      if (autopilotRef.current.targetPosition.y < 2.0) autopilotRef.current.targetPosition.y = 5.0;
    }
  };

  const handleToggleAudio = () => {
    const next = !isAudioMuted;
    setIsAudioMuted(next);
    soundEngine.setMute(next);
  };

  const handleResetUav = () => {
    physicsRef.current.reset(0);
    autopilotRef.current.setArmState('DISARMED');
    autopilotRef.current.resetIntegrators();
  };

  const handleInjectImpulse = (axis: 'roll' | 'pitch' | 'yaw') => {
    const s = physicsRef.current.getState();
    if (axis === 'roll') s.angularVelocity.p += 2.0;
    if (axis === 'pitch') s.angularVelocity.q += 2.0;
    if (axis === 'yaw') s.angularVelocity.r += 2.5;
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', background: 'var(--bg-primary)' }}>
      {/* 1. Header Control Bar */}
      <Header
        telemetry={telemetry}
        armState={autopilotRef.current.armState}
        flightMode={autopilotRef.current.flightMode}
        isAudioMuted={isAudioMuted}
        onToggleArm={handleToggleArm}
        onSelectFlightMode={handleSelectFlightMode}
        onToggleAudio={handleToggleAudio}
        onResetUav={handleResetUav}
      />

      {/* 2. Telemetry Ribbon Strip */}
      <TelemetryStrip
        telemetry={telemetry}
        windSpeed={envRef.current.update(0, 0).baseWindSpeed}
        windHeading={envRef.current.update(0, 0).windDirectionDeg}
      />

      {/* 3. Main Dashboard Workspace */}
      <div style={{ display: 'grid', gridTemplateColumns: '320px 1fr 380px', gap: '8px', padding: '4px 8px 8px 8px', flex: 1, minHeight: 0 }}>
        {/* Left Column: PFD, Virtual Sticks, Flight Recorder */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', overflowY: 'auto' }}>
          <PrimaryFlightDisplay
            telemetry={telemetry}
            targetAltitude={autopilotRef.current.targetPosition.y}
            targetHeading={autopilotRef.current.targetHeading}
          />
          <ManualControls
            pilotInput={pilotInput}
            onChangeInput={(inp) => setPilotInput((prev) => ({ ...prev, ...inp }))}
          />
          <BlackboxPlayback
            frameCount={frameCount}
            isReplaying={isReplaying}
            replayIndex={replayIndex}
            onToggleReplay={() => setIsReplaying(!isReplaying)}
            onScrub={(idx) => { setIsReplaying(false); setReplayIndex(idx); }}
            onClear={() => { flightRecorder.clear(); setFrameCount(0); }}
          />
        </div>

        {/* Center Column: 3D Flight Viewport */}
        <div style={{ display: 'flex', flexDirection: 'column', minHeight: 0 }}>
          <Viewport3D
            telemetry={telemetry}
            waypoints={waypoints}
            windVector={envRef.current.update(0, 0).windVector}
          />
        </div>

        {/* Right Column: Oscilloscope, Mission Planner, FAT Test Suite, PID Tuner */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', overflowY: 'auto' }}>
          <TelemetryGraph telemetry={telemetry} />

          {/* Right Panel Tabs */}
          <div style={{ display: 'flex', gap: '4px' }}>
            {(['FAT_SUITE', 'MISSION', 'PID_TUNER'] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setRightPanelTab(tab)}
                className="tactical-btn"
                style={{
                  flex: 1,
                  minHeight: '28px',
                  fontSize: '11px',
                  background: rightPanelTab === tab ? 'rgba(0, 242, 254, 0.2)' : 'transparent',
                  borderColor: rightPanelTab === tab ? 'var(--accent-cyan)' : 'var(--border-subtle)',
                  color: rightPanelTab === tab ? 'var(--accent-cyan)' : 'var(--text-muted)',
                }}
              >
                {tab === 'FAT_SUITE' ? 'FAT SUITE' : tab === 'MISSION' ? 'MISSION' : 'PID TUNER'}
              </button>
            ))}
          </div>

          {rightPanelTab === 'FAT_SUITE' && (
            <TestFlightSuite
              scenarios={testRunnerRef.current.scenarios}
              activeScenario={testRunnerRef.current.activeScenario}
              onStartScenario={(id) => testRunnerRef.current.startScenario(id, physicsRef.current, autopilotRef.current, envRef.current)}
              onGenerateReport={() => testRunnerRef.current.generateReport()}
            />
          )}

          {rightPanelTab === 'MISSION' && (
            <MissionPlanner
              telemetry={telemetry}
              activeWaypoints={waypoints}
              activeWpIndex={autopilotRef.current.activeWaypointIndex}
              onUploadMission={(wps) => { setWaypoints(wps); autopilotRef.current.waypoints = wps; autopilotRef.current.activeWaypointIndex = 0; }}
              onClearMission={() => { setWaypoints([]); autopilotRef.current.waypoints = []; }}
            />
          )}

          {rightPanelTab === 'PID_TUNER' && (
            <PidTuningPanel
              pidConfig={autopilotRef.current.pidConfig}
              onUpdatePid={(cfg) => { autopilotRef.current.pidConfig = cfg; }}
              onInjectImpulse={handleInjectImpulse}
            />
          )}
        </div>
      </div>
    </div>
  );
};

